function dashCounts(){const d=dashboardData,activeInc=d.incidents.filter(dashIsActiveIncident),critical=activeInc.filter(x=>String(x.severity).toLowerCase()==='critical'),pendingMaint=d.maintenance.filter(x=>!['completed','cancelled'].includes(String(x.status).toLowerCase())),today=new Date().toISOString().slice(0,10),overdue=d.maintenance.filter(x=>x.due_date&&x.due_date<today&&!['completed','cancelled'].includes(String(x.status).toLowerCase()));return {activeInc,critical,pendingMaint,overdue,roadsKm:d.roads.reduce((sum,r)=>sum+Number(r.length_m||r.official_length_m||r.geometry_length_m||0),0)/1000,inspections:d.inspections.length}}
function dashSvgBarChart(){const d=dashboardData,rows=[['Críticas',d.incidents.filter(x=>dashIsActiveIncident(x)&&String(x.severity).toLowerCase()==='critical').length,'#d75f68'],['Altas',d.incidents.filter(x=>dashIsActiveIncident(x)&&String(x.severity).toLowerCase()==='high').length,'#df9b37'],['Medias',d.incidents.filter(x=>dashIsActiveIncident(x)&&String(x.severity).toLowerCase()==='medium').length,'#5b9ad6'],['Bajas',d.incidents.filter(x=>dashIsActiveIncident(x)&&String(x.severity).toLowerCase()==='low').length,'#20a99a']];const max=Math.max(1,...rows.map(x=>x[1]));return `<div class="dash-real-bars" role="img" aria-label="Incidencias abiertas por severidad">${rows.map(([label,value,color])=>`<div class="dash-real-bar-row"><span>${label}</span><div class="dash-real-bar-track"><i style="width:${value?Math.max(2,value/max*100):0}%;background:${color}"></i></div><b>${value}</b></div>`).join('')}</div>`}
function dashTrendSvg(){const d=dashboardData,days=dashboardPeriodDays<=30?7:dashboardPeriodDays<=90?9:12,now=new Date(),points=[];for(let i=days-1;i>=0;i--){const end=new Date(now);end.setHours(23,59,59,999);end.setDate(end.getDate()-i*Math.max(1,Math.floor(dashboardPeriodDays/days)));const start=new Date(end);start.setDate(start.getDate()-Math.max(1,Math.floor(dashboardPeriodDays/days))+1);const count=(rows,key)=>rows.filter(x=>{const dt=new Date(x[key]);return !Number.isNaN(dt.getTime())&&dt>=start&&dt<=end}).length;points.push({label:end.toLocaleDateString('es-CL',{day:'2-digit',month:'short'}),ins:count(d.inspections,'inspection_date'),inc:count(d.incidents,'occurred_at'),maint:d.maintenance.filter(x=>x.completed_at&&new Date(x.completed_at)>=start&&new Date(x.completed_at)<=end).length})}const max=Math.max(1,...points.flatMap(p=>[p.ins,p.inc,p.maint]));const line=(key)=>points.map((p,i)=>`${i?'L':'M'}${points.length===1?300:i*600/(points.length-1)} ${150-p[key]/max*125}`).join(' ');return `<div class="dash-trend-wrap"><div class="dash-trend-legend"><span><i style="background:#16a394"></i>Inspecciones</span><span><i style="background:#6299df"></i>Incidencias</span><span><i style="background:#9582d6"></i>Mantenimiento cerrado</span></div><svg class="dash-trend-real" viewBox="0 0 600 170" role="img" aria-label="Tendencia temporal de actividad"><g class="dash-chart-grid"><path d="M0 25H600 M0 65H600 M0 105H600 M0 150H600"/></g><path d="${line('ins')}" fill="none" stroke="#16a394" stroke-width="3"/><path d="${line('inc')}" fill="none" stroke="#6299df" stroke-width="3"/><path d="${line('maint')}" fill="none" stroke="#9582d6" stroke-width="3"/>${points.map((p,i)=>`<text x="${points.length===1?300:i*600/(points.length-1)}" y="166" text-anchor="middle">${esc(p.label)}</text>`).join('')}</svg></div>`}
function dashRecentActivity(){const d=dashboardData,events=[...d.inspections.map(x=>({...x,_kind:'Inspección',_date:x.inspection_date||x.created_at,_title:x.title||x.code,_status:dashStatusLabel(x.status)})),...d.incidents.map(x=>({...x,_kind:'Incidencia',_date:x.occurred_at||x.created_at,_title:x.title||x.code,_status:dashSeverity(x)})),...d.maintenance.map(x=>({...x,_kind:'Mantenimiento',_date:x.updated_at||x.created_at,_title:x.title||x.code,_status:dashMaintenanceLabel(x)}))].sort((a,b)=>new Date(b._date)-new Date(a._date)).slice(0,5);if(dashboardData.loading)return '<div class="dash-empty-state">Consultando actividad real…</div>';if(!events.length)return '<div class="dash-empty-state">No hay actividad registrada en este proyecto para las fuentes consultadas.</div>';return `<div class="dash-activity-list">${events.map(x=>`<article class="dash-activity-item"><span class="dash-activity-dot ${x._kind==='Incidencia'?'is-alert':x._kind==='Mantenimiento'?'is-work':''}"></span><div><b>${esc(x._title)}</b><small>${esc(x._kind)} · ${esc(x._status||'Sin estado')}</small></div><time>${esc(dashDateLabel(x._date))}</time></article>`).join('')}</div>`}
