const GEO_OFFLINE_DB='geotracia-offline-v2';
const GEO_OFFLINE_DB_VERSION=1;
function offlineDb(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('Este navegador no admite almacenamiento local IndexedDB.'));return}const req=indexedDB.open(GEO_OFFLINE_DB,GEO_OFFLINE_DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('entries'))db.createObjectStore('entries',{keyPath:'key'});if(!db.objectStoreNames.contains('queue'))db.createObjectStore('queue',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('No se pudo abrir la base local.'));})}
async function offlinePut(store,value){const db=await offlineDb();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>{db.close();resolve(value)};tx.onerror=()=>{db.close();reject(tx.error||new Error('No se pudo guardar localmente.'))}})}
async function offlineGet(store,key){const db=await offlineDb();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),req=tx.objectStore(store).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close()})}
async function offlineAll(store){const db=await offlineDb();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),req=tx.objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close()})}
async function offlineDelete(store,key){const db=await offlineDb();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
function offlineSnapshotKey(projectId=dashboardProjectId){return `snapshot:${geoCurrentUser?.id||'guest'}:${geoOrg?.id||'unknown'}:${projectId||'none'}`}
