async function offline(){const p=await offlineLiveHtml();return `${head('Trabajo sin conexión','Prepara información territorial en el dispositivo y sincroniza al recuperar la conectividad.',btn('↻ Actualizar estado','offline-refresh')+btn('↓ Exportar respaldo','offline-export'))}<div id="offlineLiveContent">${p}</div>`}
async function renderOfflineGeometryMap(){const el=$('#offlineGeometryMap');if(!el||!window.L)return;const projectId=$('#offlineProjectSelect')?.value||dashboardProjectId||geoProjects.find(p=>p.status!=='archived')?.id;let snap=projectId?await offlineGet('entries',offlineSnapshotKey(projectId)):null;if(!snap){const all=await offlineSnapshots();snap=all.find(x=>x.projectId===projectId)||all[0]||null}if(!snap?.dashboard)return;const d=snap.dashboard;const map=L.map(el,{preferCanvas:true,zoomControl:true,attributionControl:false}).setView([-38.7359,-72.5904],8);if(navigator.onLine)L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const layers=[];for(const g of [...(d.geometries||[]),...(d.segmentGeometries||[])]){try{let gj=g.geojson;if(typeof gj==='string')gj=JSON.parse(gj);if(gj?.type==='Feature')gj=gj.geometry;if(gj?.type&&gj.coordinates){const l=L.geoJSON(gj,{style:{color:g.segment_id?'#0d968b':'#1769ee',weight:g.segment_id?4:3,opacity:.95}}).addTo(map);layers.push(l)}}catch{}}if(layers.length)map.fitBounds(L.featureGroup(layers).getBounds().pad(.08));else toast('La copia local no contiene geometrías dibujables.');setTimeout(()=>map.invalidateSize(),80);el._offlineMap=map}
