async function loadReportData(projectId=reportProjectId){
 const root=$('#reportsLiveContent');if(!root)return;
 if(!window.geoSupabase){root.innerHTML='<section class="panel"><div class="panel-body"><div class="note">Supabase no está configurado. No se mostrarán cifras de ejemplo.</div></div></section>';return}
 try{
  if(!geoCurrentUser||!geoOrg){await loadGeoProjects();}
  if(!geoOrg)throw new Error('No se encontró una organización activa para este usuario.');
  reportProjectId=projectId||'';
  if(!reportProjectId){reportLive={loading:false,error:'',roads:[],segments:[],inspections:[],inventory:[],incidents:[],maintenance:[]};root.innerHTML=`<section class="panel report-empty-state"><div class="panel-body"><h2>Selecciona un proyecto</h2><p>Los indicadores y las exportaciones aparecerán cuando selecciones un proyecto de la lista.</p>${geoProjects.length?'':'<p class="sub">No hay proyectos disponibles para esta organización o no tienes permisos para consultarlos.</p>'}</div></section>`;return}
  root.innerHTML='<section class="panel"><div class="panel-body">Consultando caminos, tramos, inspecciones, infraestructura, incidencias y mantenimiento…</div></section>';
  const client=window.geoSupabase, tables=[
   ['roads','roads'],['segments','segments'],['inspections','inspections'],['inventory','road_inventory'],['incidents','road_incidents'],['maintenance','maintenance_orders']
  ];
  const results=await Promise.all(tables.map(async ([key,table])=>{const q=await client.from(table).select('*').eq('organization_id',geoOrg.id).eq('project_id',reportProjectId).limit(5000);if(q.error)throw new Error(`No se pudo consultar ${table}: ${q.error.message}`);return [key,q.data||[]]}));
  reportLive={loading:false,error:'',...Object.fromEntries(results)};
  const d=reportLive, kmRoads=d.roads.reduce((s,r)=>s+(Number(r.length_m)||0),0)/1000, kmSegments=d.segments.reduce((s,r)=>s+Math.max(0,(Number(r.end_km)||0)-(Number(r.start_km)||0)),0);
  const km=kmRoads||kmSegments, total=d.roads.length+d.segments.length+d.inspections.length+d.inventory.length+d.incidents.length+d.maintenance.length;
  const stats=[[''+total,'Registros consultados','▤'],[km.toLocaleString('es-CL',{maximumFractionDigits:2})+' km','Longitud calculada','⌁'],[String(d.incidents.length),'Incidencias registradas','△'],[String(d.maintenance.length),'Órdenes de mantenimiento','⚒']];
  const all=[...d.inspections.map(x=>({...x,__tipo:'Inspección'})),...d.incidents.map(x=>({...x,__tipo:'Incidencia'})),...d.inventory.map(x=>({...x,__tipo:'Infraestructura'})),...d.maintenance.map(x=>({...x,__tipo:'Mantenimiento'}))].slice(0,200);
  root.innerHTML=`<div class="kpis">${stats.map((s,i)=>kpi(s[0],s[1],'Datos consultados en Supabase',s[2],i===1?'teal':i===2?'amber':i===3?'purple':'' )).join('')}</div><div class="module-layout"><div class="stack">${panel('Resumen de resultados',`<div class="panel-body"><div class="report-stats">${[['Caminos',d.roads.length,'⌁'],['Tramos',d.segments.length,'▤'],['Inspecciones',d.inspections.length,'✓'],['Infraestructura',d.inventory.length,'▦']].map(x=>`<div class="result"><span>${x[2]}</span><strong>${x[1]}</strong><small>${x[0]}</small></div>`).join('')}</div></div>`,'Totales reales del proyecto')}${panel('Registros consultados',all.length?`<div class="table-scroll"><table><thead><tr><th>TIPO</th><th>CÓDIGO</th><th>DESCRIPCIÓN</th><th>ESTADO</th><th>FECHA</th></tr></thead><tbody>${all.map(x=>`<tr><td>${esc(x.__tipo)}</td><td>${esc(x.code||'—')}</td><td>${esc(x.title||x.name||x.description||x.notes||'—')}</td><td>${esc(reportStatusLabel(x.status||x.condition||'—'))}</td><td>${esc((x.inspection_date||x.occurred_at||x.created_at||x.scheduled_date||'').toString().slice(0,10)||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel-body">No hay registros operacionales en las tablas consultadas para este proyecto.</div>','Fuente: Supabase · máximo 200 filas en pantalla')}</div><div class="stack">${panel('Exportar informe',body(`<p class="sub">Descarga los resultados reales del proyecto seleccionado en el formato que necesites.</p><div class="report-export-options">${btn('↓ Descargar CSV','reports-export','primary')}${btn('▦ Exportar para Excel','reports-export-excel')}${btn('▤ Generar PDF','reports-export-pdf')}</div><p class="sub">PDF se abre en la vista de impresión del navegador. Excel se entrega como archivo compatible con Excel.</p>`),'Formatos de exportación')}</div></div>`;
 }catch(e){reportLive={loading:false,error:e.message,roads:[],segments:[],inspections:[],inventory:[],incidents:[],maintenance:[]};root.innerHTML=`<section class="panel"><div class="panel-head"><h2>No se pudieron cargar los informes</h2></div><div class="panel-body"><div class="note">${esc(e.message||'Error de Supabase')}</div><p class="sub">Verifica que las migraciones de las tablas operacionales estén aplicadas y que RLS permita consultar el proyecto.</p>${btn('Reintentar','reports-reload','primary')}</div></section>`;}
}
function reportStatusLabel(value){const key=String(value??'').trim().toLowerCase();const labels={open:'Abierta',in_progress:'En curso',in_progress_review:'En revisión',resolved:'Resuelta',closed:'Cerrada',planned:'Programada',in_progress_work:'En ejecución',suspended:'Suspendida',completed:'Completada',cancelled:'Cancelada',active:'Activo',inactive:'Inactivo',pending:'Pendiente',approved:'Aprobado',rejected:'Rechazado',draft:'Borrador',submitted:'Enviada',under_review:'En revisión',critical:'Crítica',high:'Alta',medium:'Media',low:'Baja',good:'Bueno',fair:'Regular',poor:'Malo',operational:'Operativa',damaged:'Dañada',maintenance:'En mantenimiento'};return labels[key]||value||'—'}
function liveReportRows(){const d=reportLive;return [...d.inspections.map(x=>({...x,tipo:'Inspección'})),...d.incidents.map(x=>({...x,tipo:'Incidencia'})),...d.inventory.map(x=>({...x,tipo:'Infraestructura'})),...d.maintenance.map(x=>({...x,tipo:'Mantenimiento'}))]}
function reportExportRows(){return liveReportRows().map(r=>({'Tipo':r.tipo,'Código':r.code||'','Descripción':r.title||r.name||r.description||r.notes||'','Estado':reportStatusLabel(r.status||r.condition||''),'Fecha':(r.inspection_date||r.occurred_at||r.created_at||r.scheduled_date||'').toString().slice(0,10),'Camino':r.road_id||'','Tramo':r.segment_id||'','Progresiva km':r.km_progressive??''}))}
function exportLiveReport(){if(!reportProjectId)return toast('Selecciona un proyecto antes de exportar.');const rows=reportExportRows();if(!rows.length)return toast('No hay registros reales para exportar en este proyecto.');const cols=Object.keys(rows[0]);const csv=[cols,...rows.map(r=>cols.map(c=>r[c]))].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');exportFile(`geotracia-informe-${reportProjectId}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8');toast('CSV real exportado desde Supabase')}
function exportLiveReportExcel(){if(!reportProjectId)return toast('Selecciona un proyecto antes de exportar.');const rows=reportExportRows();if(!rows.length)return toast('No hay registros reales para exportar en este proyecto.');const cols=Object.keys(rows[0]);const table=`<table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;const html=`<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif}table{border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;text-align:left}th{background:#eaf0f7}</style></head><body><h1>Informe Geotracia</h1><p>Proyecto: ${esc(geoProjects.find(p=>p.id===reportProjectId)?.name||reportProjectId)}</p>${table}</body></html>`;exportFile(`geotracia-informe-${reportProjectId}.xls`,html,'application/vnd.ms-excel;charset=utf-8');toast('Informe compatible con Excel descargado')}
function exportLiveReportPdf(){if(!reportProjectId)return toast('Selecciona un proyecto antes de generar el PDF.');const rows=reportExportRows();if(!rows.length)return toast('No hay registros reales para generar el PDF.');const w=window.open('','_blank');if(!w)return toast('El navegador bloqueó la ventana. Permite ventanas emergentes para generar el PDF.');const title=esc(geoProjects.find(p=>p.id===reportProjectId)?.name||'Proyecto');w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Informe Geotracia</title><style>body{font:12px Arial,sans-serif;color:#1d3045;padding:24px}h1{font-size:22px}p{color:#596b7c}table{border-collapse:collapse;width:100%;margin-top:18px}th,td{border:1px solid #cbd5df;padding:7px;text-align:left;vertical-align:top}th{background:#eef3f8} @media print{button{display:none}body{padding:0}}</style></head><body><h1>Geotracia · Informe de proyecto</h1><p><b>Proyecto:</b> ${title}<br><b>Fecha de generación:</b> ${new Date().toLocaleDateString('es-CL')}<br><b>Registros incluidos:</b> ${rows.length}</p><table><thead><tr>${Object.keys(rows[0]).map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v??'')}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function updateReportProjectOptions(){const select=$('#reportProjectSelect');if(!select)return;const prior=reportProjectId;select.innerHTML='<option value="">Seleccionar proyecto…</option>'+geoProjects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${p.code?' · '+esc(p.code):''}</option>`).join('');select.disabled=!geoProjects.length;if(prior&&geoProjects.some(p=>p.id===prior)){select.value=prior}else{select.value='';reportProjectId='';const root=$('#reportsLiveContent');if(root)root.innerHTML=`<section class="panel report-empty-state"><div class="panel-body"><h2>Selecciona un proyecto</h2><p>Los indicadores y las exportaciones aparecerán cuando selecciones un proyecto de la lista.</p>${geoProjects.length?'':'<p class="sub">No hay proyectos disponibles para esta organización o no tienes permisos para consultarlos.</p>'}</div></section>`}}
function reports(){const opts=geoProjects.map(p=>`<option value="${esc(p.id)}" ${p.id===reportProjectId?'selected':''}>${esc(p.name)}${p.code?' · '+esc(p.code):''}</option>`).join('');return `${head("Informes y exportaciones","Informes calculados con registros reales de la organización en Supabase.",btn("↻ Actualizar","reports-reload"))}<section class="panel"><div class="panel-head"><div><h2>Proyecto de trabajo</h2><div class="sub">Selecciona un proyecto para consultar sus registros y generar informes.</div></div></div><div class="panel-body"><label class="field-label" for="reportProjectSelect">Proyecto</label><select class="field" id="reportProjectSelect" ${geoProjects.length?'':'disabled'}><option value="">Seleccionar proyecto…</option>${opts}</select>${geoProjectsError?`<div class="note">${esc(geoProjectsError)}</div>`:''}</div></section><div id="reportsLiveContent"><section class="panel report-empty-state"><div class="panel-body"><h2>Selecciona un proyecto</h2><p>Los indicadores, registros y formatos de exportación se cargarán después de seleccionar un proyecto.</p></div></section></div>`}
let geoUserRows=[],geoUsersLoading=false,geoUsersError="";
function usersModule(){const rows=geoUserRows;const activeRows=rows.filter(x=>x.active!==false);return `${head("Usuarios",mod(active)[3],btn("↻ Actualizar","users-reload")+btn("↓ Exportar usuarios","export-users"))}<div class="kpis">${kpi(geoUsersLoading?"…":rows.length,"Membresías encontradas","Organización actual","♙")}${kpi(activeRows.length,"Membresías activas","Estado registrado en Supabase","✓","teal")}${kpi(rows.length-activeRows.length,"Membresías inactivas","Sin acceso por membresía","×","red")}${kpi(geoOrg?esc(geoOrg.name):"Sin organización","Organización","Contexto actual","▦","purple")}</div>${geoUsersError?`<div class="note danger-note" role="alert">${esc(geoUsersError)}</div>`:""}<div class="module-layout"><div>${panel("Directorio de miembros",`<div class="table-tools"><label class="field-search">⌕ <input id="userSearch" placeholder="Buscar nombre o correo…" value="${esc(query)}"></label><select class="field" id="userState" style="max-width:160px"><option value="">Todos los estados</option><option value="Activo">Activos</option><option value="Inactivo">Inactivos</option></select></div><div id="userTable">${geoUsersLoading?'<div class="empty">Consultando membresías en Supabase…</div>':userTable()}</div><div class="pagination"><span>${rows.length} membresías devueltas por el servidor</span></div>` ,"Los cambios se guardan en Supabase y están sujetos a RLS.")}</div><div class="stack">${panel("Roles de organización",body([["owner","Propietario","Administración de la organización"],["admin","Administrador","Gestión de miembros y configuración"],["member","Miembro","Acceso operativo según permisos"],["viewer","Visualizador","Acceso de lectura cuando las políticas lo permiten"]].map(r=>settingsRow("♢",r[1],r[2])).join("")))}${panel("Invitaciones",body(`<p class="sub">La invitación requiere un endpoint seguro del servidor que cree o invite la cuenta mediante Supabase Auth. Esta pantalla no inventará invitaciones ni creará cuentas localmente.</p>${btn("Consultar requisitos de invitación","invite")}`))}</div></div>`}
function userTable(){let d=geoUserRows.filter(u=>!query||[u.display_name,u.email,u.role,u.org_name].join(" ").toLowerCase().includes(query.toLowerCase()));const state=$("#userState")?.value;if(state)d=d.filter(u=>(u.active!==false?"Activo":"Inactivo")===state);return `<div class="table-scroll"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>ORGANIZACIÓN</th><th>ESTADO</th><th>ÚLTIMO ACCESO</th><th></th></tr></thead><tbody>${d.map(u=>`<tr><td><b>${esc(u.display_name||u.email||"Miembro sin nombre")}</b><div class="cell-sub">${esc(u.email||"Correo no disponible en la membresía")}</div></td><td>${esc(u.role||"viewer")}</td><td>${esc(u.org_name||geoOrg?.name||"Organización")}</td><td>${badge(u.active===false?"Inactivo":"Activo",u.active===false?"danger":"success")}</td><td>—</td><td><div class="row-actions"><button data-member-edit="${esc(u.id)}" title="Editar rol">✎</button><button data-member-toggle="${esc(u.id)}" title="Cambiar estado">↻</button></div></td></tr>`).join("")||`<tr><td colspan="6">${geoUsersError?"No fue posible cargar el directorio.":"No hay membresías que coincidan con los filtros."}</td></tr>`}</tbody></table></div>`}
async function loadGeoUsers(){geoUsersLoading=true;geoUsersError="";geoUserRows=[];if(active==="usuarios")show();try{const c=window.geoSupabase;if(!c)throw new Error("El cliente Supabase no está configurado.");const {data:ud,error:ue}=await c.auth.getUser();if(ue)throw ue;if(!ud?.user)throw new Error("La sesión no está activa. Inicia sesión nuevamente.");geoCurrentUser=ud.user;if(!geoOrg)await loadGeoProjects();if(!geoOrg?.id)throw new Error("No se encontró una organización activa para esta cuenta.");const {data,error}=await c.rpc("geotracia_org_member_directory",{p_organization_id:geoOrg.id});if(error)throw new Error((error.message||"No fue posible consultar el directorio seguro.")+". Verifica que ejecutaste la migración 202610230002_geotracia_org_member_directory.sql en Supabase.");geoUserRows=(data||[]).map(m=>({...m,org_name:m.org_name||geoOrg.name,display_name:m.display_name||"Miembro sin nombre",email:m.email||"Correo no disponible"}));}catch(e){geoUsersError=e?.message||"No fue posible consultar las membresías.";geoUserRows=[];}finally{geoUsersLoading=false;if(active==="usuarios")show()}}
function editGeoMember(id){const m=geoUserRows.find(x=>String(x.id)===String(id));if(!m)return;dialog("Editar membresía",`<form id="memberEditForm"><div class="note">Se modificará la membresía de la organización actual. La autorización definitiva depende de las políticas RLS.</div><p><b>${esc(m.email||m.display_name||"Miembro")}</b></p><label class="field-label" for="memberRole">Rol</label><select id="memberRole" class="field">${[["owner","Propietario"],["admin","Administrador"],["member","Miembro"],["viewer","Visualizador"]].map(([v,l])=>`<option value="${v}" ${m.role===v?"selected":""}>${l}</option>`).join("")}</select></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="member-save" data-id="${esc(m.id)}">Guardar cambios</button>`)}
async function saveGeoMember(id){const m=geoUserRows.find(x=>String(x.id)===String(id));if(!m||!geoOrg)return;const role=$("#memberRole")?.value;if(!["owner","admin","member","viewer"].includes(role))return toast("Rol no válido.");try{const {error}=await window.geoSupabase.from("members").update({role}).eq("id",m.id).eq("organization_id",geoOrg.id);if(error)throw error;try{await window.geoSupabase.from("audit_logs").insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id,action:"member.role_updated",entity_table:"members",entity_id:m.id,details:{role}})}catch{}$("#dialog").close();toast("Rol actualizado en Supabase");await loadGeoUsers()}catch(e){toast("No se pudo cambiar el rol: "+(e.message||"error de permisos"))}}
async function toggleGeoMember(id){const m=geoUserRows.find(x=>String(x.id)===String(id));if(!m||!geoOrg)return;if(m.user_id===geoCurrentUser?.id)return toast("No puedes desactivar tu propia membresía desde esta pantalla.");const next=m.active===false;try{const {error}=await window.geoSupabase.from("members").update({active:next}).eq("id",m.id).eq("organization_id",geoOrg.id);if(error)throw error;try{await window.geoSupabase.from("audit_logs").insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id,action:next?"member.activated":"member.deactivated",entity_table:"members",entity_id:m.id,details:{active:next}})}catch{}toast(next?"Membresía activada":"Membresía desactivada");await loadGeoUsers()}catch(e){toast("No se pudo cambiar el estado: "+(e.message||"error de permisos"))}}

function legacyDemoUserTable(){let d=users.filter(u=>!query||[u.name,u.email,u.role,u.org].join(" ").toLowerCase().includes(query.toLowerCase()));if($("#userState")?.value)d=d.filter(u=>u.state===$("#userState").value);return `<div class="table-scroll"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>ORGANIZACIÓN</th><th>ESTADO</th><th>ÚLTIMO ACCESO</th><th></th></tr></thead><tbody>${d.map(u=>`<tr><td><b>${esc(u.name)}</b><div class="cell-sub">${esc(u.email)}</div></td><td>${esc(u.role)}</td><td>${esc(u.org)}</td><td>${badge(u.state,u.state==="Activo"?"success":"danger")}</td><td>${esc(u.last)}</td><td><div class="row-actions"><button data-user-edit="${esc(u.email)}">✎</button><button data-user-toggle="${esc(u.email)}">↻</button></div></td></tr>`).join("")||`<tr><td colspan="6">Sin coincidencias</td></tr>`}</tbody></table></div>`}
let userSpaceState={loading:false,preferences:null,audit:[],error:'',user:null};
let userSpaceAvatarFile=null,userSpaceAvatarPreviewUrl='';
const USER_SPACE_AVATAR_BUCKET='geotracia-avatars';
function userSpaceAvatarPreview(url){const img=$('#uspAvatarImage'),empty=$('#uspAvatarEmpty');if(img){if(url){img.src=url;img.hidden=false;if(empty)empty.hidden=true;}else{img.removeAttribute('src');img.hidden=true;if(empty)empty.hidden=false;}}}
function userSpaceChooseAvatar(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){userSpaceNotice('Formato no válido. Usa JPG, PNG o WebP.',true);$('#uspAvatarFile').value='';return;}if(file.size>5*1024*1024){userSpaceNotice('La fotografía supera el máximo de 5 MB.',true);$('#uspAvatarFile').value='';return;}userSpaceAvatarFile=file;if(userSpaceAvatarPreviewUrl)URL.revokeObjectURL(userSpaceAvatarPreviewUrl);userSpaceAvatarPreviewUrl=URL.createObjectURL(file);userSpaceAvatarPreview(userSpaceAvatarPreviewUrl);const label=$('#uspAvatarFileName');if(label)label.textContent=file.name;userSpaceNotice('Fotografía seleccionada. Pulsa «Guardar perfil» para subirla.');}
async function userSpaceLoadAvatar(user){const path=user?.user_metadata?.avatar_path;if(!path){userSpaceAvatarPreview('');const label=$('#uspAvatarFileName');if(label)label.textContent='No has seleccionado una fotografía.';return;}try{const {data,error}=await window.geoSupabase.storage.from(USER_SPACE_AVATAR_BUCKET).createSignedUrl(path,3600);if(error)throw error;userSpaceAvatarPreview(data?.signedUrl||'');const label=$('#uspAvatarFileName');if(label)label.textContent='Fotografía de perfil guardada';}catch(e){console.warn('[GEOTRACIA USER SPACE] No se pudo cargar la foto de perfil:',e?.message||e);userSpaceAvatarPreview('');const label=$('#uspAvatarFileName');if(label)label.textContent='Fotografía guardada; no se pudo mostrar. Verifica el bucket y sus políticas.';}}
function userSpaceFormatAction(action){const a=String(action||'').toLowerCase();if(a.includes('created')||a.includes('create'))return 'Creación';if(a.includes('updated')||a.includes('update'))return 'Edición';if(a.includes('deleted')||a.includes('delete'))return 'Eliminación';if(a.includes('sync'))return 'Sincronización';if(a.includes('auth')||a.includes('session')||a.includes('sign'))return 'Acceso y seguridad';return action||'Actividad';}
function userSpaceModuleLabel(module){const map={profile:'Perfil',preferences:'Preferencias',projects:'Proyectos',operations:'Operaciones',inspections:'Inspecciones',inventory:'Inventario vial',incidents:'Incidencias',maintenance:'Mantenimiento',offline:'Trabajo sin conexión',auth:'Acceso y seguridad'};return map[module]||module||'Cuenta';}
function userSpaceNotice(message,isError=false){const el=$('#userSpaceStatus');if(el){el.textContent=message;el.hidden=false;el.classList.toggle('error',!!isError);el.setAttribute('role','status');}else toast(message)}
async function userSpaceRequireUser(){const client=window.geoSupabase;if(!client)throw new Error('Supabase no está configurado.');const {data,error}=await client.auth.getUser();if(error)throw error;if(!data?.user)throw new Error('La sesión no está activa. Inicia sesión nuevamente.');geoCurrentUser=data.user;return data.user;}

function userSpaceReadFormPreferences(){return {date_format:$('#uspDate')?.value||'DD/MM/YYYY',distance_unit:$('#uspDistance')?.value||'km',timezone:$('#uspTimezone')?.value||'America/Santiago',density:$('#uspDensity')?.value||'comfortable',notifications:$('#uspNotifications')?.checked===true,confirm_destructive:$('#uspConfirm')?.checked===true,offline_notice:$('#uspOffline')?.checked===true};}
function userSpaceApplyPreferences(p={}){const set=(id,v)=>{const el=$('#'+id);if(el&&v!==undefined&&v!==null)el.value=String(v)};set('uspDate',p.date_format||'DD/MM/YYYY');set('uspDistance',p.distance_unit||'km');set('uspTimezone',p.timezone||'America/Santiago');set('uspDensity',p.density||'comfortable');for(const [id,key,def] of [['uspNotifications','notifications',true],['uspConfirm','confirm_destructive',true],['uspOffline','offline_notice',true]]){const el=$('#'+id);if(el)el.checked=p[key]===undefined?def:!!p[key];}}
function userSpaceRenderAudit(rows){const tbody=$('#userAuditRows');if(!tbody)return;tbody.innerHTML=rows.length?rows.map(r=>`<tr><td>${esc(r.created_at?new Date(r.created_at).toLocaleString('es-CL'):'—')}</td><td>${esc(userSpaceFormatAction(r.action))}<div class="cell-sub">${esc(r.action||'')}</div></td><td>${esc(userSpaceModuleLabel(r.module))}</td><td>${badge(r.result==='success'?'Correcto':r.result==='failed'?'Fallido':r.result||'Registrado',r.result==='success'?'success':r.result==='failed'?'danger':'info')}</td><td>${esc(r.details?.summary||r.details?.field||r.details?.changed_fields?.join?.(', ')||'Evento de cuenta')}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty-state compact"><h3>Sin resultados</h3><p>No hay eventos que coincidan con los filtros.</p></div></td></tr>';}
function userSpaceFilterAudit(){const from=$('#uaFrom')?.value||'',to=$('#uaTo')?.value||'',action=$('#uaAction')?.value||'',module=$('#uaModule')?.value||'',q=($('#uaSearch')?.value||'').trim().toLowerCase();const rows=(userSpaceState.audit||[]).filter(r=>{const day=(r.created_at||'').slice(0,10),a=String(r.action||'').toLowerCase(),m=String(r.module||'').toLowerCase(),blob=[r.action,r.module,r.entity_id,JSON.stringify(r.details||{})].join(' ').toLowerCase();let actionOk=true;if(action==='create')actionOk=a.includes('create');else if(action==='update')actionOk=a.includes('update');else if(action==='delete')actionOk=a.includes('delete');else if(action==='sync')actionOk=a.includes('sync');else if(action==='auth')actionOk=['auth','session','sign'].some(x=>a.includes(x));return (!from||day>=from)&&(!to||day<=to)&&actionOk&&(!module||m===module)&&(!q||blob.includes(q));});userSpaceRenderAudit(rows);return rows;}
async function loadUserSpaceData(){if(active!=='configuracion')return;userSpaceState.loading=true;userSpaceState.error='';try{const client=window.geoSupabase,user=await userSpaceRequireUser();if(!geoOrg)await loadGeoProjects();if(active!=='configuracion')return;const meta=user.user_metadata||{};const name=meta.display_name||meta.full_name||meta.name||'';const nameEl=$('#uspName'),emailEl=$('#uspEmail'),phoneEl=$('#uspPhone'),orgEl=$('#uspOrg');if(nameEl)nameEl.value=name;if(emailEl)emailEl.value=user.email||'';if(phoneEl)phoneEl.value=meta.phone||meta.phone_number||'';await userSpaceLoadAvatar(user);if(orgEl)orgEl.value=geoOrg?.name||'Sin organización activa';userSpaceState.user=user;
 const {data:prefs,error:prefErr}=await client.from('geotracia_user_preferences').select('preferences,updated_at').eq('user_id',user.id).maybeSingle();if(prefErr)throw prefErr;userSpaceState.preferences=prefs?.preferences||{};userSpaceApplyPreferences(userSpaceState.preferences);
 const {data:events,error:eventErr}=await client.from('geotracia_user_audit_events').select('id,organization_id,user_id,action,module,result,details,created_at').eq('user_id',user.id).order('created_at',{ascending:false}).limit(300);if(eventErr)throw eventErr;let legacyEvents=[];try{const legacy=await client.from('audit_logs').select('id,organization_id,actor_id,action,entity_table,entity_id,details,created_at').eq('actor_id',user.id).order('created_at',{ascending:false}).limit(300);if(!legacy.error)legacyEvents=(legacy.data||[]).map(r=>({id:'legacy-'+r.id,user_id:r.actor_id,organization_id:r.organization_id,action:r.action,module:({projects:'projects',geotracia_operations:'operations',geotracia_project_access:'operations',inspections:'inspections',road_inventory:'inventory',road_incidents:'incidents',maintenance_orders:'maintenance'})[r.entity_table]||r.entity_table||'other',result:'success',details:{...(r.details||{}),entity_id:r.entity_id,summary:(r.details||{}).name||(r.details||{}).title||r.entity_table||'Acción registrada'},created_at:r.created_at}));}catch(legacyErr){console.warn('[GEOTRACIA USER SPACE] No se pudo consultar audit_logs heredada:',legacyErr?.message||legacyErr)}userSpaceState.audit=[...(events||[]),...legacyEvents].sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0)).slice(0,500);
 const queue=await offlineQueueRows().catch(()=>[]);const snapshots=await offlineSnapshots().catch(()=>[]);const setText=(id,value)=>{const el=$(id);if(el)el.textContent=String(value)};setText('#uspKpiEvents',userSpaceState.audit.length);setText('#uspKpiChanges',userSpaceState.audit.filter(x=>/updated|created|deleted|update|create|delete/.test(x.action||'')).length);setText('#uspKpiPending',queue.length);setText('#uspKpiSessions',user.id?'Activa':'—');setText('#uspSessionIdentity',user.email||user.id);setText('#uspLastAccess',user.last_sign_in_at?new Date(user.last_sign_in_at).toLocaleString('es-CL'):'No informado por Auth');const recent=$('#uspActivitySummary');if(recent)recent.innerHTML=userSpaceState.audit.slice(0,5).map(r=>settingsRow('◷',userSpaceFormatAction(r.action),`${userSpaceModuleLabel(r.module)} · ${r.created_at?new Date(r.created_at).toLocaleString('es-CL'):'fecha no disponible'}`,r.result==='failed'?'Fallido':'Registrado')).join('')||'<div class="empty-state compact"><h3>Sin actividad registrada</h3><p>Las acciones de esta cuenta aparecerán aquí cuando se registren.</p></div>';const storage=$('#uspStorageSummary');if(storage)storage.innerHTML=settingsRow('☁','Registros locales',`${queue.length} pendientes de sincronización`,queue.length?'Pendiente':'Al día')+settingsRow('↻','Proyectos preparados',`${snapshots.length} proyectos disponibles en este dispositivo`,snapshots.length?'Disponible':'Vacío')+settingsRow('▤','Almacenamiento utilizado','El navegador no expone una medición exacta fiable por módulo','No medido');const tbody=$('#userAuditRows');if(tbody)userSpaceFilterAudit();const note=$('#userSpaceStatus');if(note){note.hidden=true;note.textContent='';}userSpaceState.error='';
 }catch(e){userSpaceState.error=e?.message||'Error de lectura';userSpaceNotice('No se pudo cargar el espacio personal: '+userSpaceState.error,true);console.error('[GEOTRACIA USER SPACE] Error de lectura',e);}finally{userSpaceState.loading=false;}}
async function saveUserSpaceProfile(){const form=$('#userProfileForm');if(form&&!form.reportValidity())return;const button=$('[data-action=\"user-space-save-profile\"]');if(button){button.disabled=true;button.textContent='Guardando…'}try{const client=window.geoSupabase,user=await userSpaceRequireUser();const display_name=$('#uspName')?.value.trim()||'',phone=$('#uspPhone')?.value.trim()||'';let avatarPath=user.user_metadata?.avatar_path||null;if(userSpaceAvatarFile){const file=userSpaceAvatarFile,ext=({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'})[file.type];avatarPath=`${user.id}/avatar.${ext}`;const {error:uploadError}=await client.storage.from(USER_SPACE_AVATAR_BUCKET).upload(avatarPath,file,{upsert:true,contentType:file.type,cacheControl:'3600'});if(uploadError)throw new Error('No se pudo subir la fotografía. Verifica el bucket geotracia-avatars y sus políticas: '+uploadError.message);}const {data,error}=await client.auth.updateUser({data:{...user.user_metadata,display_name,phone,...(avatarPath?{avatar_path:avatarPath}:{})}});if(error)throw error;geoCurrentUser=data.user||user;userSpaceAvatarFile=null;if(userSpaceAvatarPreviewUrl){URL.revokeObjectURL(userSpaceAvatarPreviewUrl);userSpaceAvatarPreviewUrl='';}await loadUserSpaceData();userSpaceNotice('Perfil y fotografía guardados correctamente.');toast('Perfil actualizado en Supabase Auth');}catch(e){userSpaceNotice('No se pudo guardar el perfil: '+(e?.message||'error desconocido'),true);}finally{if(button){button.disabled=false;button.textContent='Guardar perfil'}}}
async function saveUserSpacePreferences(){const form=$('#userPreferencesForm');if(form&&!form.reportValidity())return;try{const user=await userSpaceRequireUser();const preferences=userSpaceReadFormPreferences();const payload={user_id:user.id,organization_id:geoOrg?.id||null,preferences,updated_at:new Date().toISOString()};const {error}=await window.geoSupabase.from('geotracia_user_preferences').upsert(payload,{onConflict:'user_id'});if(error)throw error;userSpaceState.preferences=preferences;userSpaceNotice('Preferencias guardadas correctamente.');toast('Preferencias guardadas en Supabase');await loadUserSpaceData();}catch(e){userSpaceNotice('No se pudieron guardar las preferencias: '+(e?.message||'error desconocido'),true);}}
async function loadUserSpaceAudit(){try{await userSpaceRequireUser();const {data,error}=await window.geoSupabase.from('geotracia_user_audit_events').select('id,organization_id,user_id,action,module,result,details,created_at').eq('user_id',geoCurrentUser.id).order('created_at',{ascending:false}).limit(300);if(error)throw error;userSpaceState.audit=data||[];const rows=userSpaceFilterAudit();toast(`Auditoría actualizada: ${rows.length} eventos coinciden con los filtros.`);}catch(e){userSpaceNotice('No se pudo consultar la auditoría: '+(e?.message||'error desconocido'),true);}}
function exportUserSpaceAudit(){const rows=userSpaceFilterAudit();if(!rows.length)return toast('No hay eventos reales para exportar.');const cols=['created_at','action','module','result','details'];const csv=[['Fecha y hora','Acción','Módulo','Resultado','Detalle'],...rows.map(r=>[r.created_at,r.action,r.module,r.result,JSON.stringify(r.details||{})])].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');exportFile('geotracia-mi-auditoria.csv','\ufeff'+csv,'text/csv;charset=utf-8');toast('Auditoría propia exportada a CSV');}
