let geoSubscriptionPlans=[], geoOrgSubscription=null, geoSubscriptionRequests=[], geoSubscriptionLoading=false, geoSubscriptionError='', geoBillingCycle='monthly';
function admin(){return `${head("Administración y suscripciones",mod(active)[3],btn("↻ Actualizar","subscription-reload")+btn("Ver usuarios","go-users","primary"))}<div id="subscriptionAdminContent"><div class="panel"><div class="panel-body"><p>Consultando planes y suscripción de la organización…</p></div></div></div>`}
async function loadSubscriptionAdmin(){
 const root=$('#subscriptionAdminContent'); if(!root||!window.geoSupabase)return;
 geoSubscriptionLoading=true; root.innerHTML='<div class="panel"><div class="panel-body"><p>Cargando información comercial desde Supabase…</p></div></div>';
 try{
  const client=window.geoSupabase; const {data:u,error:ue}=await client.auth.getUser(); if(ue)throw ue; geoCurrentUser=u.user; if(!geoCurrentUser)throw new Error('Inicia sesión para consultar la suscripción.');
  if(!geoOrg){const {data:m,error:me}=await client.from('members').select('organization_id,role,organizations(id,name)').eq('user_id',geoCurrentUser.id).eq('active',true).limit(1);if(me)throw me;const row=m?.[0];if(row)geoOrg={id:row.organization_id,name:row.organizations?.name||'Organización',role:row.role};}
  if(!geoOrg)throw new Error('Tu usuario no tiene una membresía activa de organización.');
  const [pr,su,re]=await Promise.all([
   client.from('geotracia_subscription_plans').select('*').eq('active',true).order('sort_order'),
   client.from('geotracia_organization_subscriptions').select('*,geotracia_subscription_plans(name,monthly_price_clp,annual_price_clp,max_operators)').eq('organization_id',geoOrg.id).maybeSingle(),
   client.from('geotracia_subscription_change_requests').select('id,requested_plan_id,billing_cycle,status,notes,created_at').eq('organization_id',geoOrg.id).order('created_at',{ascending:false}).limit(5)
  ]);
  if(pr.error)throw pr.error;if(su.error)throw su.error;if(re.error)throw re.error;
  geoSubscriptionPlans=pr.data||[];geoOrgSubscription=su.data||null;geoSubscriptionRequests=re.data||[];
  const sub=geoOrgSubscription, money=n=>n==null?'Personalizado':new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n), date=d=>d?new Date(d).toLocaleDateString('es-CL'):'No definida';
  const statusLabel={pending:'Pendiente',trialing:'Prueba',active:'Activa',past_due:'Pago pendiente',suspended:'Suspendida',cancelled:'Cancelada',expired:'Vencida'};
  root.innerHTML=`<div class="kpis">${kpi(esc(geoOrg.name),'Organización','Espacio de trabajo','▦')}${kpi(sub?.geotracia_subscription_plans?.name||geoSubscriptionPlans.find(p=>p.id===sub?.plan_id)?.name||'Sin plan','Plan actual',sub?statusLabel[sub.status]||sub.status:'No contratado','▤','teal')}${kpi(sub?.operator_limit??sub?.operators_limit??sub?.geotracia_subscription_plans?.max_operators??'—','Límite de operadores','Definido por suscripción','♙','purple')}${kpi(date(sub?.current_period_end),'Vigencia','Fin del periodo actual','◷','amber')}</div>
  <div class="module-layout"><div class="stack">${panel('Suscripción de la organización',sub?`<div class="settings-row"><span class="setting-icon">▤</span><span class="setting-copy"><b>${esc(sub.geotracia_subscription_plans?.name||geoSubscriptionPlans.find(p=>p.id===sub.plan_id)?.name||sub.plan_id)}</b><small>${(sub.billing_cycle||sub.billing_period)==='annual'?'Facturación anual':sub.billing_cycle==='custom'?'Contrato personalizado':'Facturación mensual'} · Vigencia hasta ${date(sub.current_period_end)}</small></span>${badge(statusLabel[sub.status]||sub.status,sub.status==='active'?'success':sub.status==='suspended'?'danger':'warning')}</div><div class="note">Los límites se aplican en servidor. La solicitud de cambio no procesa cobros ni activa automáticamente un plan.</div>`:`<div class="note">Esta organización todavía no tiene una suscripción registrada. Selecciona un plan para enviar una solicitud de contratación.</div>`,'Estado comercial')}
  ${panel('Solicitudes recientes',geoSubscriptionRequests.length?`<div class="table-scroll"><table><thead><tr><th>PLAN SOLICITADO</th><th>PERIODO</th><th>ESTADO</th><th>FECHA</th></tr></thead><tbody>${geoSubscriptionRequests.map(r=>`<tr><td>${esc(geoSubscriptionPlans.find(p=>p.id===r.requested_plan_id)?.name||r.requested_plan_id)}</td><td>${r.billing_cycle==='annual'?'Anual':r.billing_cycle==='custom'?'Personalizado':'Mensual'}</td><td>${badge(r.status==='pending'?'Pendiente':r.status==='approved'?'Aprobada':r.status==='rejected'?'Rechazada':'Cancelada',r.status==='approved'?'success':r.status==='rejected'?'danger':'warning')}</td><td>${date(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">No hay solicitudes de cambio de plan.</p>','Historial de solicitudes')}</div>
  <div class="stack">${panel('Planes y suscripciones',`<div class="billing-toolbar"><div><b>Elige tu plan</b><p class="sub">Cambia entre precios mensuales y anuales sin salir de esta tabla.</p></div><div class="billing-switch" role="group" aria-label="Periodicidad de facturación"><button type="button" class="billing-option ${geoBillingCycle==='monthly'?'active':''}" data-action="subscription-cycle" data-cycle="monthly" aria-pressed="${geoBillingCycle==='monthly'}">Mensual</button><button type="button" class="billing-option ${geoBillingCycle==='annual'?'active':''}" data-action="subscription-cycle" data-cycle="annual" aria-pressed="${geoBillingCycle==='annual'}">Anual</button></div></div><div class="plans-grid">${geoSubscriptionPlans.map(p=>{const annual=geoBillingCycle==='annual';const institutional=p.id==='institucional'||p.custom_limits;const shown=annual?p.annual_price_clp:p.monthly_price_clp;const displayPrice=institutional?(annual?'Desde '+money(3999900):money(399990)+' – '+money(1200000)):money(shown);const suffix=institutional?(annual?'/ año + IVA':'/ mes + IVA'):(annual?'/ año + IVA':'/ mes + IVA');return `<article class="plan ${p.id==='empresa'?'featured':''}"><div class="plan-topline"><span class="plan-kicker">GEOTRACIA</span>${p.id==='empresa'?badge('Más elegido','success'):''}</div><h3>${esc(p.name)}</h3><div class="price">${displayPrice}<small style="font-size:10px;font-weight:600"> ${suffix}</small></div>${annual&&!institutional&&p.monthly_price_clp?`<p class="annual-equivalent">Equivale a ${money(Math.round(p.annual_price_clp/12))} al mes</p>`:''}<p>${institutional?'Capacidad y servicios definidos por contrato':`${p.max_operators} operador${p.max_operators===1?'':'es'} incluidos`}</p><ul><li>✓ Gestión de proyectos territoriales</li><li>✓ Roles y permisos según perfil</li><li>✓ Límites asociados al plan</li>${p.id==='institucional'?'<li>✓ Unidades y estructura jerárquica</li>':''}</ul>${btn(sub?.plan_id===p.id&&sub?.billing_cycle===geoBillingCycle?'Plan actual':'Elegir '+(annual?'anual':'mensual'),'subscription-request',sub?.plan_id===p.id&&sub?.billing_cycle===geoBillingCycle?'':'primary',`data-plan-id="${esc(p.id)}" data-cycle="${geoBillingCycle}"`)}</article>`}).join('')}</div><p class="billing-footnote">Valores en pesos chilenos (CLP), más IVA. La selección anual muestra el total del año. Los planes con precio continúan al checkout seguro de Flow; la licencia solo se activa tras confirmación del pago en el servidor.</p>`,'Selecciona una periodicidad y compara los cuatro planes')}
  ${panel('Consideraciones',`<div class="settings-row"><span class="setting-icon">♢</span><span class="setting-copy"><b>Solicitud no equivale a pago</b><small>La activación comercial requiere validación administrativa y una integración de facturación.</small></span></div><div class="settings-row"><span class="setting-icon">♙</span><span class="setting-copy"><b>Roles independientes del plan</b><small>El plan define límites; los roles determinan las acciones permitidas.</small></span></div><div class="settings-row"><span class="setting-icon">▤</span><span class="setting-copy"><b>Datos aislados por organización</b><small>La visibilidad depende de membresía y políticas RLS.</small></span></div>`,'Reglas de operación')}</div></div>`;
 }catch(e){geoSubscriptionError=e?.message||'Error desconocido';root.innerHTML=`<div class="panel"><div class="panel-head"><h3>No se pudo cargar la administración</h3></div><div class="panel-body"><p>${esc(geoSubscriptionError)}</p><div class="note">Comprueba que ejecutaste la migración <code>202610230003_geotracia_subscriptions_admin.sql</code> en Supabase y que la organización y las políticas de membresía están configuradas.</div>${btn('Reintentar','subscription-reload','primary')}</div></div>`;}
 finally{geoSubscriptionLoading=false;}
}
async function requestSubscriptionPlan(planId,cycle=geoBillingCycle){
 const p=geoSubscriptionPlans.find(x=>String(x.id)===String(planId));
 if(!p||!geoOrg||!geoCurrentUser)return toast('No se pudo validar el plan o la organización.');
 const billingCycle=cycle==='annual'?'annual':'monthly';
 // El plan institucional/personalizado conserva la solicitud de propuesta; los planes con precio van directamente al checkout.
 if(p.custom_limits===true||p.is_custom===true||String(p.code||p.id).toLowerCase()==='institucional'){
  return dialog('Solicitar propuesta institucional',`<div class="note">El plan <b>${esc(p.name)}</b> requiere una propuesta comercial. No se procesará un cobro automático.</div><form id="subscriptionRequestForm" class="form-grid"><div><label class="field-label" for="subscriptionCycle">Periodicidad</label><select class="field" id="subscriptionCycle"><option value="monthly" ${billingCycle==='monthly'?'selected':''}>Mensual</option><option value="annual" ${billingCycle==='annual'?'selected':''}>Anual</option><option value="custom">Contrato personalizado</option></select></div><div class="full"><label class="field-label" for="subscriptionNotes">Observaciones (opcional)</label><textarea class="field" id="subscriptionNotes" rows="3" placeholder="Requerimientos o consultas comerciales"></textarea></div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="subscription-request-confirm" data-plan-id="${esc(planId)}">Enviar solicitud</button>`);
 }
 if(!window.geoSupabase?.functions?.invoke)return toast('No está disponible el cliente de funciones de Supabase.');
 const button=document.querySelector(`[data-action="subscription-request"][data-plan-id="${CSS.escape(String(planId))}"][data-cycle="${billingCycle}"]`);
 const originalText=button?.textContent||'Contratar plan';
 if(button){button.disabled=true;button.dataset.originalText=originalText;button.textContent='Conectando con Flow…';}
 try{
  const {data,error}=await window.geoSupabase.functions.invoke('geotracia-flow-create-payment',{body:{organization_id:geoOrg.id,plan_id:p.id,billing_cycle:billingCycle}});
  if(error){
   let detail=error.message||'No se pudo contactar el servicio de pagos.';
   try{const context=error.context;if(context&&typeof context.json==='function'){const payload=await context.json();detail=payload?.error||payload?.message||detail;}}catch{}
   throw new Error(detail);
  }
  if(!data?.ok||!data?.checkout_url)throw new Error(data?.error||'Flow no devolvió la URL de pago. Verifica la configuración del servicio de pagos.');
  const checkout=new URL(data.checkout_url);
  if(checkout.protocol!=='https:'||!(checkout.hostname==='flow.cl'||checkout.hostname.endsWith('.flow.cl')))throw new Error('La URL de checkout de Flow no es válida.');
  window.location.assign(checkout.toString());
 }catch(e){
  console.error('Geotracia checkout:',e);
  toast('No se pudo iniciar el pago: '+(e?.message||'revisa la configuración de Flow en Supabase'));
  if(button){button.disabled=false;button.textContent=originalText;}
 }
}
async function confirmSubscriptionRequest(planId){const p=geoSubscriptionPlans.find(x=>x.id===planId);if(!p||!geoOrg||!geoCurrentUser)return toast('No se pudo validar la solicitud.');const cycle=$('#subscriptionCycle')?.value||'monthly';try{const {error}=await window.geoSupabase.from('geotracia_subscription_change_requests').insert({organization_id:geoOrg.id,requested_plan_id:p.id,billing_cycle:cycle,requested_by:geoCurrentUser.id,notes:$('#subscriptionNotes')?.value.trim()||null});if(error)throw error;$('#dialog').close();toast('Solicitud enviada. La suscripción no se ha activado ni cobrado.');await loadSubscriptionAdmin()}catch(e){toast('No se pudo enviar la solicitud: '+(e?.message||'error de permisos'))}}

