function inventoryLineSlice(geojson,startKm,endKm,declaredLengthM){
 if(!geojson||!Number.isFinite(Number(startKm))||!Number.isFinite(Number(endKm))||Number(startKm)<0||Number(endKm)<=Number(startKm))return null;
 let lines=[];if(geojson.type==='LineString')lines=[geojson.coordinates||[]];else if(geojson.type==='MultiLineString')lines=geojson.coordinates||[];else if(geojson.type==='GeometryCollection')lines=(geojson.geometries||[]).flatMap(g=>g.type==='LineString'?[g.coordinates||[]]:g.type==='MultiLineString'?(g.coordinates||[]):[]);
 const pts=lines.flat().filter(p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(Number(p[0]))&&Number.isFinite(Number(p[1])));if(pts.length<2)return null;
 const hav=(a,b)=>{const rad=v=>v*Math.PI/180,dLat=rad(b[1]-a[1]),dLon=rad(b[0]-a[0]),q=Math.sin(dLat/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(dLon/2)**2;return 6371008.8*2*Math.atan2(Math.sqrt(q),Math.sqrt(Math.max(0,1-q)))};
 const lengths=[];let total=0;for(let i=1;i<pts.length;i++){const d=hav(pts[i-1],pts[i]);lengths.push(d);total+=d}if(total<=0)return null;
 const declared=Number(declaredLengthM)>0?Number(declaredLengthM):total;const a=Math.max(0,Math.min(1,Number(startKm)*1000/declared))*total,b=Math.max(0,Math.min(1,Number(endKm)*1000/declared))*total;if(b<=a)return null;
 const at=distance=>{let rem=distance;for(let i=1;i<pts.length;i++){const d=lengths[i-1];if(rem<=d||i===pts.length-1){const f=d?Math.max(0,Math.min(1,rem/d)):0;return [Number(pts[i-1][0])+(Number(pts[i][0])-Number(pts[i-1][0]))*f,Number(pts[i-1][1])+(Number(pts[i][1])-Number(pts[i-1][1]))*f]}rem-=d}return pts[pts.length-1].slice(0,2)};
 const out=[at(a)];let cumulative=0;for(let i=1;i<pts.length;i++){cumulative+=lengths[i-1];if(cumulative>a&&cumulative<b)out.push([Number(pts[i][0]),Number(pts[i][1])])}out.push(at(b));return out.length>=2?out:null;
}
