function inventoryPointFor(item){const g=inventoryRoadGeometries[item?.road_id];const derived=g?inventoryLinePoint(g.geojson,item?.km_progressive,g.length_m):null;if(derived)return {...derived,derived:true};if(item?.latitude!=null&&item?.longitude!=null&&Number.isFinite(Number(item.latitude))&&Number.isFinite(Number(item.longitude)))return {lat:Number(item.latitude),lng:Number(item.longitude),legacy:true};return null}
function refreshInventoryDerivedPoints(){inventoryRows=inventoryRows.map(x=>{const p=inventoryPointFor(x);return {...x,_mapLat:p?.lat??null,_mapLng:p?.lng??null}})}
async function loadInventoryData(projectId=inventoryProjectId){
 const client=window.geoSupabase;inventoryProjectId=projectId||geoProjects.find(p=>p.status!=='archived')?.id||geoProjects[0]?.id||'';inventoryError='';inventoryLoading=true;
 if(active==='inventario')show();
 if(!client){inventoryError='No hay conexión con Supabase.';inventoryLoading=false;if(active==='inventario')show();return}
 if(!geoOrg||!inventoryProjectId){inventoryRows=[];inventoryRoads=[];inventorySegments=[];inventoryLoading=false;if(active==='inventario')show();return}
 try{
  const [r,s,i]=await Promise.all([
   client.from('roads').select('id,code,name,road_type,surface_type,length_m,project_id,organization_id').eq('organization_id',geoOrg.id).eq('project_id',inventoryProjectId).order('code'),
   client.from('segments').select('id,road_id,code,start_km,end_km,project_id,organization_id').eq('organization_id',geoOrg.id).eq('project_id',inventoryProjectId).order('start_km'),
   client.from('road_inventory').select('id,organization_id,project_id,road_id,segment_id,code,name,asset_type,condition,status,km_progressive,latitude,longitude,quantity,unit,installed_at,notes,metadata,created_at,updated_at').eq('organization_id',geoOrg.id).eq('project_id',inventoryProjectId).order('created_at',{ascending:false})
  ]);
  for(const x of [r,s,i])if(x.error)throw x.error;
  inventoryRoads=r.data||[];inventorySegments=s.data||[];inventoryRows=i.data||[];inventoryRoadGeometries={};
  // La ubicación se deriva de la progresiva sobre la geometría real del camino.
  const geoResult=await client.rpc('geotracia_inventory_road_geometries',{p_project_id:inventoryProjectId});
  if(geoResult.error)throw new Error('No se pudieron consultar las geometrías viales para calcular coordenadas desde la progresiva: '+geoResult.error.message);
  for(const g of (geoResult.data||[])){let geom=g.road_geojson||g.geojson||g.geom_geojson;if(typeof geom==='string'){try{geom=JSON.parse(geom)}catch{geom=null}}if(g.road_id&&geom)inventoryRoadGeometries[g.road_id]={geojson:geom,length_m:g.length_m==null?null:Number(g.length_m)}}
  refreshInventoryDerivedPoints();
 }catch(e){inventoryError=inventoryErrorMessage(e);inventoryRows=[];}
 finally{inventoryLoading=false;if(active==='inventario')show()}
}
function inventoryErrorMessage(e){const m=e?.message||'No fue posible consultar el inventario vial.';if(/relation .*road_inventory.* does not exist|schema cache/i.test(m))return 'La tabla road_inventory todavía no existe. Ejecuta la migración SQL incluida en este paquete y pulsa Actualizar.';if(/permission denied|row-level security|violates row-level/i.test(m))return 'Supabase rechazó la operación por permisos RLS. Verifica tu organización y el rol de tu usuario.';return 'Error en inventario vial: '+m}
function inventoryModule(){
 const options=geoProjects.filter(p=>p.status!=='archived').map(p=>`<option value="${esc(p.id)}" ${p.id===inventoryProjectId?'selected':''}>${esc((p.code?p.code+' · ':'')+p.name)}</option>`).join('');
 const roadById=id=>inventoryRoads.find(r=>r.id===id),segmentById=id=>inventorySegments.find(s=>s.id===id);
 const rows=inventoryRows.map(x=>{const r=roadById(x.road_id),seg=segmentById(x.segment_id);const conditionTone=({'Bueno':'success','Operativo':'success','Regular':'warning','Requiere revisión':'warning','Malo':'danger','Crítico':'danger'})[x.condition]||'info';const statusLabel=({'active':'Activo','inactive':'Inactivo','maintenance':'En mantenimiento','retired':'Retirado'})[x.status]||x.status;return `<tr class="${selectedInventoryId===x.id?'inventory-row-selected':''}"><td><b>${esc(x.code)}</b><div class="cell-sub">${esc(x.name)}</div>${x.metadata?.inventory_photo?'<div class="cell-sub">📷 Con fotografía</div>':''}</td><td>${esc(x.asset_type)}</td><td><b>${esc(r?.code||'—')}</b><div class="cell-sub">${esc(r?.name||'')}</div></td><td>${seg?esc(seg.code):'Camino completo'}${x.km_progressive!=null?`<div class="cell-sub">Km ${Number(x.km_progressive).toFixed(3)}</div>`:''}</td><td>${badge(x.condition||'Sin evaluar',conditionTone)}</td><td>${esc(statusLabel)}</td><td>${Number(x.quantity||1).toLocaleString('es-CL')} ${esc(x.unit||'unidad')}</td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" data-action="inventory-locate" data-id="${esc(x.id)}">Ubicar</button><button class="btn" data-action="inventory-view" data-id="${esc(x.id)}">Ver</button><button class="btn" data-action="inventory-edit" data-id="${esc(x.id)}">Editar</button></div></td></tr>`}).join('');
 const critical=inventoryRows.filter(x=>['Malo','Crítico'].includes(x.condition)).length,needs=inventoryRows.filter(x=>['Regular','Requiere revisión','Sin evaluar'].includes(x.condition)).length;
 return `${head('Inventario vial','Catastro real de infraestructura, activos y equipamiento asociado a caminos y tramos.',btn('↻ Actualizar','inventory-reload')+btn('＋ Nuevo elemento','inventory-new','primary'))}
 <section class="panel"><div class="panel-head"><div><h2>Proyecto de trabajo</h2><div class="sub">El inventario se consulta y guarda en Supabase, separado por organización y proyecto.</div></div></div><div class="panel-body"><label class="field-label" for="inventoryProjectSelect">Proyecto</label><select id="inventoryProjectSelect" class="field" ${options?'':'disabled'}>${options||'<option value="">No hay proyectos disponibles</option>'}</select></div></section>
 ${inventoryError?`<div class="note" style="margin-top:12px;border-color:#e7a1a1;color:#9b2525">${esc(inventoryError)}</div>`:''}${inventoryLoading?'<section class="panel" style="margin-top:12px"><div class="panel-body">Consultando inventario, caminos y tramos en Supabase…</div></section>':''}
 <div class="kpis" style="margin-top:12px">${kpi(inventoryRows.length,'Elementos inventariados','Registros persistidos','▤')}${kpi(inventoryRows.filter(x=>x.status==='active').length,'Activos','En servicio','✓','teal')}${kpi(needs,'Revisión requerida','Condición regular o sin evaluar','◷','amber')}${kpi(critical,'En mal estado','Requieren intervención','△','red')}</div>
 <section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Inventario de infraestructura vial</h2><div class="sub">${inventoryRows.length} elementos · ${inventoryRoads.length} caminos · ${inventorySegments.length} tramos disponibles</div></div><button class="btn primary" data-action="inventory-new" ${!inventoryRoads.length?'disabled':''}>＋ Nuevo elemento</button></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO / NOMBRE</th><th>TIPO DE ACTIVO</th><th>CAMINO</th><th>TRAMO / PROGRESIVA</th><th>CONDICIÓN</th><th>ESTADO</th><th>CANTIDAD</th><th>ACCIONES</th></tr></thead><tbody>${rows||`<tr><td colspan="8"><div class="empty">${inventoryLoading?'Cargando…':inventoryRoads.length?'No hay elementos de inventario registrados para este proyecto. Usa «Nuevo elemento» para registrar el primero.':'No hay caminos disponibles en este proyecto. Registra primero un camino.'}</div></td></tr>`}</tbody></table></div></div></section>
 <section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Mapa de elementos inventariados</h2><div class="sub">Un marcador por activo con coordenadas. Selecciona un marcador para destacar el registro; doble clic para abrir su ficha y fotografía.</div></div><span class="badge">${inventoryRows.filter(x=>x._mapLat!=null&&x._mapLng!=null).length} ubicados</span></div><div class="panel-body"><div id="inventoryMap" class="inventory-map" style="height:360px;min-height:300px;width:100%;border-radius:12px;overflow:hidden" role="application" aria-label="Mapa de activos inventariados"></div><div id="inventoryMapStatus" class="sub" style="margin-top:8px">${inventoryRows.some(x=>x._mapLat!=null&&x._mapLng!=null)?'Selecciona un activo de la tabla o un marcador del mapa.':'No hay activos con ubicación calculable. Revisa geometría del camino y progresivas.'}</div></div></section>
 <div class="note" style="margin-top:12px">Los registros se guardan en PostgreSQL mediante Supabase. Las fotografías se almacenan en Supabase Storage y sus referencias en los metadatos del activo.</div>`;
}
function newInventoryItem(item=null){if(!geoOrg||!inventoryProjectId)return toast('Selecciona un proyecto válido.');if(!inventoryRoads.length)return toast('Este proyecto no tiene caminos registrados.');inventoryPhotoFile=null;if(inventoryPhotoPreviewUrl){URL.revokeObjectURL(inventoryPhotoPreviewUrl);inventoryPhotoPreviewUrl=''}const v=(k,d='')=>item?.[k]??d;const roadOptions=inventoryRoads.map(r=>`<option value="${esc(r.id)}" ${v('road_id',inventoryRoads[0]?.id)===r.id?'selected':''}>${esc(r.code+' · '+r.name)}</option>`).join('');const segs=inventorySegments.map(s=>{const r=inventoryRoads.find(q=>q.id===s.road_id);return `<option value="${esc(s.id)}" data-road-id="${esc(s.road_id)}" ${v('segment_id')===s.id?'selected':''}>${esc(s.code+' · '+(r?.code||'Camino')+' · '+Number(s.start_km||0).toFixed(3)+'–'+Number(s.end_km||0).toFixed(3)+' km')}</option>`}).join('');const types=['Señal vertical','Señal horizontal','Defensa caminera','Alcantarilla / drenaje','Puente / estructura','Iluminación','Paradero','Hito / delineador','Barreras y seguridad','Mobiliario urbano','Otro'];const conds=['Sin evaluar','Bueno','Operativo','Regular','Requiere revisión','Malo','Crítico'];const statuses=[['active','Activo'],['maintenance','En mantenimiento'],['inactive','Inactivo'],['retired','Retirado']];const existingPhoto=item?.metadata?.inventory_photo;let photoPreview=existingPhoto?`<div id="invPhotoCurrent" class="full"><img src="" id="invPhotoCurrentImg" alt="Fotografía actual" style="max-width:100%;max-height:180px;border-radius:10px;display:none"><div class="sub">Este activo ya tiene una fotografía. Si seleccionas otra, se reemplazará la referencia.</div></div>`:'';dialog(item?'Editar elemento de inventario':'Nuevo elemento de inventario',`<form id="inventoryForm" class="form-grid"><div class="note full">El registro se guardará en Supabase y quedará vinculado al camino y, si corresponde, al tramo.</div><div><label class="field-label" for="invCode">Código *</label><input class="field" id="invCode" required maxlength="60" value="${esc(v('code','INV-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-6)))}"></div><div><label class="field-label" for="invName">Nombre / descripción *</label><input class="field" id="invName" required maxlength="180" value="${esc(v('name'))}" placeholder="Ej. Señal Pare norte"></div><div><label class="field-label" for="invType">Tipo de activo *</label><select class="field" id="invType">${types.map(t=>`<option ${v('asset_type',types[0])===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div><label class="field-label" for="invCondition">Condición *</label><select class="field" id="invCondition">${conds.map(t=>`<option ${v('condition','Sin evaluar')===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="full"><label class="field-label" for="invRoad">Camino *</label><select class="field" id="invRoad" required>${roadOptions}</select></div><div class="full"><label class="field-label" for="invSegment">Tramo (opcional)</label><select class="field" id="invSegment"><option value="">Camino completo / sin tramo específico</option>${segs}</select></div><div><label class="field-label" for="invKm">Progresiva (km)</label><input class="field" id="invKm" type="number" min="0" step="0.001" value="${esc(v('km_progressive'))}" placeholder="Ej. 12.300"></div><div><label class="field-label" for="invQuantity">Cantidad *</label><input class="field" id="invQuantity" type="number" min="0.001" step="0.001" required value="${esc(v('quantity',1))}"></div><div><label class="field-label" for="invUnit">Unidad</label><select class="field" id="invUnit">${['unidad','m','m²','m³','km','conjunto'].map(u=>`<option ${v('unit','unidad')===u?'selected':''}>${u}</option>`).join('')}</select></div><div><label class="field-label" for="invStatus">Estado operativo</label><select class="field" id="invStatus">${statuses.map(([k,l])=>`<option value="${k}" ${v('status','active')===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label class="field-label" for="invInstalled">Fecha de instalación (opcional)</label><input class="field" id="invInstalled" type="date" value="${esc(v('installed_at'))}"></div><div class="full"><label class="field-label" for="invNotes">Observaciones</label><textarea class="field" id="invNotes" rows="3" maxlength="5000">${esc(v('notes'))}</textarea></div><div class="full"><h3 style="margin:4px 0">Ubicación automática por progresiva</h3><div class="sub">GEOTRACIA calcula el punto sobre la geometría del camino usando la progresiva indicada. No necesitas ingresar latitud ni longitud. La precisión depende de que la geometría y el kilometraje de referencia estén correctamente calibrados.</div><div id="invDerivedLocationStatus" class="sub" style="margin:8px 0">La ubicación se calculará al seleccionar camino y progresiva.</div><div id="invLocationMap" class="inventory-location-map"></div></div><div class="full"><h3 style="margin:4px 0">Fotografía del elemento</h3><div class="sub">Toma una fotografía o selecciona una imagen de la galería. JPG, PNG o WebP; máximo 10 MB.</div><div class="inventory-photo-actions"><label class="btn" for="invPhotoCamera">📷 Tomar fotografía</label><input id="invPhotoCamera" class="inventory-file-input" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"><label class="btn" for="invPhotoGallery">▧ Elegir de galería</label><input id="invPhotoGallery" class="inventory-file-input" type="file" accept="image/jpeg,image/png,image/webp"></div><div id="invPhotoPreview" class="inventory-photo-preview">${existingPhoto?'Hay una fotografía guardada. Selecciona una nueva si deseas reemplazarla.':'No se ha seleccionado una fotografía.'}</div>${photoPreview}</div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="inventory-save" data-id="${esc(item?.id||'')}">Guardar elemento</button>`);const road=$('#invRoad'),seg=$('#invSegment');const filter=()=>{[...seg.options].forEach(o=>{if(o.value)o.hidden=o.dataset.roadId!==road.value});if(seg.selectedOptions[0]?.hidden)seg.value=''};road.addEventListener('change',filter);filter();if(existingPhoto?.path&&window.geoSupabase){window.geoSupabase.storage.from(existingPhoto.bucket||'geotracia-evidencias').createSignedUrl(existingPhoto.path,300).then(({data})=>{const im=$('#invPhotoCurrentImg');if(im&&data?.signedUrl){im.src=data.signedUrl;im.style.display='block'}})}initInventoryLocationPicker(item);}
function initInventoryLocationPicker(item){const el=$('#invLocationMap');if(!el||!window.L)return;let map=null,marker=null;const initial=inventoryPointFor(item||{});const center=initial?[initial.lat,initial.lng]:[-38.7359,-72.5904];setTimeout(()=>{if(!$('#invLocationMap'))return;map=L.map(el,{doubleClickZoom:false,scrollWheelZoom:true}).setView(center,initial?16:7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);const status=$('#invDerivedLocationStatus');const update=()=>{const roadId=$('#invRoad')?.value,km=$('#invKm')?.value;const p=inventoryPointFor({road_id:roadId,km_progressive:km===''?null:Number(km)});if(p){if(marker)marker.setLatLng([p.lat,p.lng]);else marker=L.circleMarker([p.lat,p.lng],{radius:9,color:'#0f766e',fillColor:'#2dd4bf',fillOpacity:.95,weight:3}).addTo(map);map.setView([p.lat,p.lng],Math.max(map.getZoom(),15));if(status)status.textContent=`Ubicación calculada: ${p.lat.toFixed(6)}, ${p.lng.toFixed(6)} (derivada de la progresiva).`; }else{if(marker){map.removeLayer(marker);marker=null}if(status)status.textContent='No se pudo calcular la ubicación. Verifica que el camino tenga geometría y que la progresiva esté informada y calibrada.'}};$('#invRoad')?.addEventListener('change',update);$('#invKm')?.addEventListener('input',update);update();requestAnimationFrame(()=>map.invalidateSize());el._inventoryLeaflet=map},180)}
function handleInventoryPhoto(input){const file=input?.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){toast('Usa una imagen JPG, PNG o WebP.');input.value='';return}if(file.size>10*1024*1024){toast('La imagen supera el límite de 10 MB.');input.value='';return}const body=$('#dialogBody'),scrollTop=body?.scrollTop||0;inventoryPhotoFile=file;if(inventoryPhotoPreviewUrl)URL.revokeObjectURL(inventoryPhotoPreviewUrl);inventoryPhotoPreviewUrl=URL.createObjectURL(file);const box=$('#invPhotoPreview');if(box)box.innerHTML=`<img src="${inventoryPhotoPreviewUrl}" alt="Vista previa de la fotografía" style="display:block;width:100%;max-width:420px;max-height:240px;object-fit:contain;border-radius:10px;margin:0 auto"><div class="sub">${esc(file.name)} · ${(file.size/1024/1024).toFixed(2)} MB</div>`;requestAnimationFrame(()=>{if(body){body.scrollTop=scrollTop;body.style.scrollBehavior='auto'}const dlg=$('#dialog');if(dlg?.open)dlg.style.overflow='hidden'})}
async function saveInventoryItem(id=''){const form=$('#inventoryForm');if(!form?.reportValidity()||!geoOrg||!inventoryProjectId||!window.geoSupabase)return;const road=inventoryRoads.find(r=>r.id===$('#invRoad').value);if(!road)return toast('Selecciona un camino válido.');const segmentId=$('#invSegment').value||null,segment=inventorySegments.find(s=>s.id===segmentId);if(segmentId&&(!segment||segment.road_id!==road.id))return toast('El tramo seleccionado no pertenece al camino.');const km=$('#invKm').value===''?null:Number($('#invKm').value);if(km!=null&&segment&&(km<Number(segment.start_km)||km>Number(segment.end_km)))return toast('La progresiva debe estar dentro del rango del tramo seleccionado.');const calculatedPoint=inventoryPointFor({road_id:road.id,km_progressive:km});if(km!=null&&!calculatedPoint)return toast('No se pudo calcular la ubicación: el camino necesita geometría vial válida y una progresiva compatible.');const old=inventoryRows.find(x=>x.id===id);const oldMeta=old?.metadata&&typeof old.metadata==='object'?old.metadata:{};const payload={organization_id:geoOrg.id,project_id:inventoryProjectId,road_id:road.id,segment_id:segmentId,code:$('#invCode').value.trim(),name:$('#invName').value.trim(),asset_type:$('#invType').value,condition:$('#invCondition').value,status:$('#invStatus').value,km_progressive:km,quantity:Number($('#invQuantity').value),unit:$('#invUnit').value,installed_at:$('#invInstalled').value||null,notes:$('#invNotes').value.trim(),metadata:oldMeta,updated_at:new Date().toISOString()};const button=$('[data-action="inventory-save"]');if(button){button.disabled=true;button.textContent='Guardando…'}try{let q=window.geoSupabase.from('road_inventory');let saved;if(id){const {data,error}=await q.update(payload).eq('id',id).eq('organization_id',geoOrg.id).eq('project_id',inventoryProjectId).select('id').single();if(error)throw error;saved=data}else{payload.created_by=geoCurrentUser?.id||null;const {data,error}=await q.insert(payload).select('id').single();if(error)throw error;saved=data}if(!saved?.id)throw new Error('Supabase no confirmó el guardado.');if(inventoryPhotoFile){const file=inventoryPhotoFile;const ext=({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'})[file.type]||'jpg';const path=`${geoOrg.id}/road-inventory/${saved.id}/${Date.now()}.${ext}`;const {error:upErr}=await window.geoSupabase.storage.from('geotracia-evidencias').upload(path,file,{contentType:file.type,upsert:true});if(upErr)throw new Error('El elemento se guardó, pero falló la carga de la fotografía: '+upErr.message);const meta={...oldMeta,inventory_photo:{bucket:'geotracia-evidencias',path,file_name:file.name,mime_type:file.type,size:file.size,uploaded_at:new Date().toISOString()}};const {error:metaErr}=await window.geoSupabase.from('road_inventory').update({metadata:meta,updated_at:new Date().toISOString()}).eq('id',saved.id).eq('organization_id',geoOrg.id).eq('project_id',inventoryProjectId);if(metaErr)throw new Error('El elemento y la fotografía se cargaron, pero no se pudo guardar la referencia: '+metaErr.message)}$('#dialog').close();inventoryPhotoFile=null;if(inventoryPhotoPreviewUrl){URL.revokeObjectURL(inventoryPhotoPreviewUrl);inventoryPhotoPreviewUrl=''}toast(id?'Elemento de inventario actualizado en Supabase':'Elemento de inventario guardado en Supabase');await loadInventoryData(inventoryProjectId)}catch(err){console.error('[GEOTRACIA] Error guardando inventario:',err);toast('No se pudo completar el guardado: '+(err?.message||err?.details||'Error desconocido de Supabase'));if(button){button.disabled=false;button.textContent='Guardar elemento'}}}
async function viewInventoryItem(id){const x=inventoryRows.find(r=>r.id===id);if(!x)return;const road=inventoryRoads.find(r=>r.id===x.road_id),seg=inventorySegments.find(s=>s.id===x.segment_id);let photoHtml='<div class="full"><label class="field-label">Fotografía del elemento</label><p>No hay fotografía adjunta.</p></div>';const photo=x.metadata?.inventory_photo;if(photo?.path&&window.geoSupabase){const {data,error}=await window.geoSupabase.storage.from(photo.bucket||'geotracia-evidencias').createSignedUrl(photo.path,300);if(!error&&data?.signedUrl)photoHtml=`<div class="full"><label class="field-label">Fotografía del elemento</label><a href="${esc(data.signedUrl)}" target="_blank" rel="noopener"><img src="${esc(data.signedUrl)}" alt="Fotografía de ${esc(x.name)}" style="max-width:100%;max-height:320px;object-fit:contain;border-radius:12px"></a><div class="sub">${esc(photo.file_name||'Fotografía adjunta')}</div></div>`;else photoHtml='<div class="full"><label class="field-label">Fotografía del elemento</label><p>No se pudo abrir la imagen. Comprueba los permisos de Storage.</p></div>';}dialog(esc(x.name),`<div class="form-grid">${photoHtml}<div><label class="field-label">Código</label>${esc(x.code)}</div><div><label class="field-label">Tipo</label>${esc(x.asset_type)}</div><div class="full"><label class="field-label">Camino</label>${esc(road?.code||'—')} · ${esc(road?.name||'')}</div><div><label class="field-label">Tramo</label>${esc(seg?.code||'Camino completo')}</div><div><label class="field-label">Progresiva</label>${x.km_progressive==null?'—':Number(x.km_progressive).toFixed(3)+' km'}</div><div><label class="field-label">Coordenadas</label>${x.latitude!=null&&x.longitude!=null?`${Number(x.latitude).toFixed(6)}, ${Number(x.longitude).toFixed(6)}`:'Sin ubicación geográfica'}</div><div><label class="field-label">Condición</label>${esc(x.condition)}</div><div><label class="field-label">Estado</label>${esc(({'active':'Activo','maintenance':'En mantenimiento','inactive':'Inactivo','retired':'Retirado'})[x.status]||x.status)}</div><div><label class="field-label">Cantidad</label>${Number(x.quantity||1)} ${esc(x.unit||'unidad')}</div><div><label class="field-label">Instalado</label>${esc(x.installed_at||'—')}</div><div class="full"><label class="field-label">Observaciones</label><p>${esc(x.notes||'Sin observaciones.')}</p></div></div>`,`<button class="btn" data-close>Cerrar</button><button class="btn" data-action="inventory-locate" data-id="${esc(x.id)}">Ubicar en mapa</button><button class="btn primary" data-action="inventory-edit" data-id="${esc(x.id)}">Editar elemento</button>`)}
function renderInventoryMap(){const el=$('#inventoryMap');if(!el||!window.L)return;if(inventoryMapInstance){try{inventoryMapInstance.remove()}catch{}inventoryMapInstance=null;inventoryMapMarkers={}}const map=L.map(el,{doubleClickZoom:false}).setView([-38.7359,-72.5904],7);inventoryMapInstance=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);const located=inventoryRows.filter(x=>x._mapLat!=null&&x._mapLng!=null&&Number.isFinite(Number(x._mapLat))&&Number.isFinite(Number(x._mapLng)));located.forEach(x=>{const selected=x.id===selectedInventoryId;const marker=L.circleMarker([Number(x._mapLat),Number(x._mapLng)],{radius:selected?10:7,color:selected?'#0f766e':'#2563eb',weight:selected?4:2,fillColor:selected?'#2dd4bf':'#60a5fa',fillOpacity:.9});marker.bindTooltip(`${esc(x.code)} · ${esc(x.name)}`);marker.on('click',()=>selectInventoryOnMap(x.id,false));marker.on('dblclick',e=>{L.DomEvent.stop(e);viewInventoryItem(x.id)});marker.addTo(map);inventoryMapMarkers[x.id]=marker});if(located.length){const bounds=L.latLngBounds(located.map(x=>[Number(x._mapLat),Number(x._mapLng)]));map.fitBounds(bounds,{padding:[24,24],maxZoom:16});if(located.length===1)map.setZoom(16)}setTimeout(()=>map.invalidateSize(),100)}
function selectInventoryOnMap(id,openDetail=true){const x=inventoryRows.find(r=>r.id===id);if(!x)return;selectedInventoryId=id;document.querySelectorAll('#content .inventory-row-selected').forEach(r=>r.classList.remove('inventory-row-selected'));const row=[...document.querySelectorAll('#content tbody tr')].find(r=>r.querySelector(`[data-id="${CSS.escape(id)}"]`));if(row)row.classList.add('inventory-row-selected');const marker=inventoryMapMarkers[id];if(marker&&inventoryMapInstance){inventoryMapInstance.setView(marker.getLatLng(),Math.max(inventoryMapInstance.getZoom(),15),{animate:true});marker.setStyle({radius:11,color:'#0f766e',weight:4,fillColor:'#2dd4bf'});Object.entries(inventoryMapMarkers).forEach(([key,m])=>{if(key!==id)m.setStyle({radius:7,color:'#2563eb',weight:2,fillColor:'#60a5fa'})});const status=$('#inventoryMapStatus');if(status)status.textContent=`Seleccionado: ${x.code} · ${x.name}`;}else{const status=$('#inventoryMapStatus');if(status)status.textContent=`${x.code} no tiene una ubicación calculable. Verifica la geometría del camino y su progresiva.`;const mapEl=$('#inventoryMap');if(mapEl)mapEl.scrollIntoView({behavior:'smooth',block:'center'})}if(openDetail)viewInventoryItem(id)}
function editInventoryItem(id){const x=inventoryRows.find(r=>r.id===id);if(x)newInventoryItem(x)}
async function loadIncidentData(projectId=incidentProjectId){
 const client=window.geoSupabase;incidentProjectId=projectId||geoProjects.find(p=>p.status!=='archived')?.id||geoProjects[0]?.id||'';incidentError='';incidentLoading=true;if(active==='incidencias')show();
 if(!client){incidentError='No hay conexión con Supabase.';incidentLoading=false;if(active==='incidencias')show();return}
 if(!geoOrg||!incidentProjectId){incidentRows=[];incidentRoads=[];incidentSegments=[];incidentLoading=false;if(active==='incidencias')show();return}
 try{
  const [r,s,i]=await Promise.all([
   client.from('roads').select('id,code,name,road_type,surface_type,length_m,project_id,organization_id').eq('organization_id',geoOrg.id).eq('project_id',incidentProjectId).order('code'),
   client.from('segments').select('id,road_id,code,start_km,end_km,project_id,organization_id').eq('organization_id',geoOrg.id).eq('project_id',incidentProjectId).order('start_km'),
   client.from('road_incidents').select('id,organization_id,project_id,road_id,segment_id,code,title,incident_type,severity,status,km_progressive,occurred_at,description,action_taken,metadata,created_at,updated_at').eq('organization_id',geoOrg.id).eq('project_id',incidentProjectId).order('created_at',{ascending:false})
  ]);for(const x of [r,s,i])if(x.error)throw x.error;incidentRoads=r.data||[];incidentSegments=s.data||[];incidentRows=i.data||[];incidentRoadGeometries={};
  const g=await client.rpc('geotracia_inventory_road_geometries',{p_project_id:incidentProjectId});if(g.error)throw new Error('No se pudieron cargar geometrías para ubicar incidencias: '+g.error.message);
  for(const x of(g.data||[])){let geom=x.road_geojson||x.geojson||x.geom_geojson;if(typeof geom==='string'){try{geom=JSON.parse(geom)}catch{geom=null}}if(x.road_id&&geom)incidentRoadGeometries[x.road_id]={geojson:geom,length_m:x.length_m==null?null:Number(x.length_m)}}
  incidentRows=incidentRows.map(x=>{const geom=incidentRoadGeometries[x.road_id];const p=geom?inventoryLinePoint(geom.geojson,x.km_progressive,geom.length_m):null;return {...x,_mapLat:p?.lat??null,_mapLng:p?.lng??null}});
 }catch(e){incidentError='Error al consultar incidencias: '+(e?.message||'Error desconocido');incidentRows=[]}
 finally{incidentLoading=false;if(active==='incidencias')show()}
}
function incidentsModule(){
 const opts=geoProjects.filter(p=>p.status!=='archived').map(p=>`<option value="${esc(p.id)}" ${p.id===incidentProjectId?'selected':''}>${esc((p.code?p.code+' · ':'')+p.name)}</option>`).join('');
 const road=id=>incidentRoads.find(x=>x.id===id),seg=id=>incidentSegments.find(x=>x.id===id);
 const statusLabel=v=>({'open':'Abierta','in_progress':'En atención','resolved':'Resuelta','closed':'Cerrada','draft':'Borrador','archived':'Archivada'})[v]||v;
 const rows=incidentRows.map(x=>`<tr class="${selectedIncidentId===x.id?'inventory-row-selected':''}"><td><b>${esc(x.code)}</b><div class="cell-sub">${esc(x.title)}</div>${x.metadata?.incident_photo?'<div class="cell-sub">📷 Con fotografía</div>':''}</td><td>${esc(x.incident_type)}</td><td><b>${esc(road(x.road_id)?.code||'—')}</b><div class="cell-sub">${esc(road(x.road_id)?.name||'')}</div></td><td>${esc(seg(x.segment_id)?.code||'Camino completo')}<div class="cell-sub">${x.km_progressive==null?'Sin progresiva':'Km '+Number(x.km_progressive).toFixed(3)}</div></td><td>${badge(({critical:'Crítica',high:'Alta',medium:'Media',low:'Baja'})[x.severity]||x.severity||'Sin clasificar',x.severity==='critical'?'danger':x.severity==='high'?'warning':'info')}</td><td>${badge(statusLabel(x.status),x.status==='resolved'||x.status==='closed'?'success':x.status==='in_progress'?'warning':'danger')}</td><td><button class="btn" data-action="incident-locate" data-id="${esc(x.id)}">Ubicar</button> <button class="btn" data-action="incident-view" data-id="${esc(x.id)}">Ver</button> <button class="btn" data-action="incident-edit-status" data-id="${esc(x.id)}">Estado</button></td></tr>`).join('');
 const open=incidentRows.filter(x=>['open','draft'].includes(x.status)).length,progress=incidentRows.filter(x=>x.status==='in_progress').length,critical=incidentRows.filter(x=>x.severity==='critical'&&!['resolved','closed'].includes(x.status)).length,located=incidentRows.filter(x=>x._mapLat!=null&&x._mapLng!=null).length;
 return `${head('Incidencias','Registra daños y eventos viales con progresiva, evidencia fotográfica y seguimiento real en Supabase.',btn('↻ Actualizar','incident-reload')+btn('＋ Nueva incidencia','incident-new','primary'))}
 <section class="panel"><div class="panel-head"><div><h2>Proyecto de trabajo</h2><div class="sub">Incidencias vinculadas al proyecto, camino y tramo seleccionados.</div></div></div><div class="panel-body"><label class="field-label" for="incidentProjectSelect">Proyecto</label><select id="incidentProjectSelect" class="field" ${opts?'':'disabled'}>${opts||'<option value="">No hay proyectos disponibles</option>'}</select></div></section>
 ${incidentError?`<div class="note" style="margin-top:12px;border-color:#e7a1a1;color:#9b2525">${esc(incidentError)}</div>`:''}${incidentLoading?'<section class="panel"><div class="panel-body">Consultando incidencias en Supabase…</div></section>':''}
 <div class="kpis" style="margin-top:12px">${kpi(incidentRows.length,'Incidencias registradas','Persistidas en Supabase','△')}${kpi(open,'Abiertas','Pendientes de atención','◷','amber')}${kpi(progress,'En atención','Trabajos en curso','⚒','teal')}${kpi(critical,'Críticas','Requieren prioridad','!','red')}</div>
 <section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Registro de incidencias</h2><div class="sub">${incidentRows.length} incidencias · ${incidentRoads.length} caminos · ${incidentSegments.length} tramos · ${located} ubicadas en el mapa</div></div><button class="btn primary" data-action="incident-new" ${!incidentRoads.length?'disabled':''}>＋ Nueva incidencia</button></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO / DESCRIPCIÓN</th><th>TIPO</th><th>CAMINO</th><th>TRAMO / PROGRESIVA</th><th>SEVERIDAD</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>${rows||`<tr><td colspan="7"><div class="empty">${incidentLoading?'Cargando…':incidentRoads.length?'No hay incidencias registradas en este proyecto.':'No hay caminos disponibles para registrar incidencias.'}</div></td></tr>`}</tbody></table></div></div></section>
 <section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Mapa de incidencias</h2><div class="sub">Un marcador por incidencia ubicada mediante su progresiva sobre la geometría vial. Un clic selecciona; doble clic abre la ficha y fotografía.</div></div><span class="badge">${located} ubicadas</span></div><div class="panel-body"><div id="incidentMap" class="inventory-map" style="height:360px;min-height:300px;width:100%;border-radius:12px;overflow:hidden" role="application" aria-label="Mapa de incidencias"></div><div id="incidentMapStatus" class="sub" style="margin-top:8px">${located?'Selecciona un marcador para revisar la incidencia.':'No hay incidencias con progresiva y geometría calculable.'}</div></div></section>
 <div class="note" style="margin-top:12px">La ubicación se calcula desde la progresiva y la geometría del camino. Las fotografías se guardan en el bucket privado geotracia-evidencias.</div>`;
}
function renderIncidentMap(){const el=$('#incidentMap');if(!el||!window.L)return;if(incidentMapInstance){try{incidentMapInstance.remove()}catch{}incidentMapInstance=null;incidentMapMarkers={}}const map=L.map(el,{doubleClickZoom:false}).setView([-38.7359,-72.5904],7);incidentMapInstance=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);const located=incidentRows.filter(x=>x._mapLat!=null&&x._mapLng!=null);located.forEach(x=>{const selected=x.id===selectedIncidentId;const color=x.severity==='critical'?'#dc2626':x.severity==='high'?'#ea580c':x.severity==='medium'?'#d97706':'#2563eb';const m=L.circleMarker([Number(x._mapLat),Number(x._mapLng)],{radius:selected?10:7,color:selected?'#0f766e':color,weight:selected?4:2,fillColor:selected?'#2dd4bf':color,fillOpacity:.9});m.bindTooltip(`${esc(x.code)} · ${esc(x.title)}`);m.on('click',()=>selectIncidentOnMap(x.id,false));m.on('dblclick',e=>{L.DomEvent.stop(e);viewIncident(x.id)});m.addTo(map);incidentMapMarkers[x.id]=m});if(located.length){map.fitBounds(L.latLngBounds(located.map(x=>[Number(x._mapLat),Number(x._mapLng)])),{padding:[24,24],maxZoom:16});if(located.length===1)map.setZoom(16)}setTimeout(()=>map.invalidateSize(),100)}
function selectIncidentOnMap(id,openDetail=false){const x=incidentRows.find(r=>r.id===id);if(!x)return;selectedIncidentId=id;const marker=incidentMapMarkers[id];if(marker&&incidentMapInstance){incidentMapInstance.setView(marker.getLatLng(),Math.max(incidentMapInstance.getZoom(),15),{animate:true});Object.entries(incidentMapMarkers).forEach(([key,m])=>m.setStyle(key===id?{radius:11,color:'#0f766e',weight:4,fillColor:'#2dd4bf'}:{radius:7,color:incidentRows.find(q=>q.id===key)?.severity==='critical'?'#dc2626':'#2563eb',weight:2,fillColor:'#60a5fa'}));const status=$('#incidentMapStatus');if(status)status.textContent=`Seleccionada: ${x.code} · ${x.title}`;}else{const status=$('#incidentMapStatus');if(status)status.textContent=`${x.code} no tiene ubicación calculable. Verifica la progresiva y geometría del camino.`;$('#incidentMap')?.scrollIntoView({behavior:'smooth',block:'center'})}document.querySelectorAll('#content .inventory-row-selected').forEach(r=>r.classList.remove('inventory-row-selected'));if(openDetail)viewIncident(id)}
function newIncident(item=null){if(!geoOrg||!incidentProjectId)return toast('Selecciona un proyecto válido.');if(!incidentRoads.length)return toast('Este proyecto no tiene caminos registrados.');incidentPhotoFile=null;if(incidentPhotoPreviewUrl){URL.revokeObjectURL(incidentPhotoPreviewUrl);incidentPhotoPreviewUrl=''}const v=(k,d='')=>item?.[k]??d;const roadOptions=incidentRoads.map(r=>`<option value="${esc(r.id)}" ${v('road_id',incidentRoads[0]?.id)===r.id?'selected':''}>${esc(r.code+' · '+r.name)}</option>`).join('');const segOptions=incidentSegments.map(s=>{const r=incidentRoads.find(q=>q.id===s.road_id);return `<option value="${esc(s.id)}" data-road-id="${esc(s.road_id)}" ${v('segment_id')===s.id?'selected':''}>${esc(s.code+' · '+(r?.code||'Camino')+' · '+Number(s.start_km||0).toFixed(3)+'–'+Number(s.end_km||0).toFixed(3)+' km')}</option>`}).join('');const oldPhoto=item?.metadata?.incident_photo;dialog(item?'Editar incidencia':'Nueva incidencia',`<form id="incidentForm" class="form-grid"><div class="note full">La ubicación se calcula automáticamente desde la progresiva y la geometría del camino.</div><div><label class="field-label" for="icCode">Código</label><input class="field" id="icCode" required maxlength="60" value="${esc(v('code','INC-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-6)))}"></div><div><label class="field-label" for="icType">Tipo de incidencia</label><select class="field" id="icType">${['Bache','Fisura de pavimento','Deterioro de calzada','Drenaje obstruido','Señalización dañada','Derrumbe / talud','Inundación','Obstáculo en calzada','Daño estructural','Otro'].map(t=>`<option ${v('incident_type','Bache')===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="full"><label class="field-label" for="icTitle">Descripción breve</label><input class="field" id="icTitle" required maxlength="180" value="${esc(v('title',''))}" placeholder="Describe el problema detectado"></div><div><label class="field-label" for="icRoad">Camino</label><select class="field" id="icRoad">${roadOptions}</select></div><div><label class="field-label" for="icSegment">Tramo (opcional)</label><select class="field" id="icSegment"><option value="">Camino completo</option>${segOptions}</select></div><div><label class="field-label" for="icKm">Progresiva (km)</label><input class="field" id="icKm" type="number" min="0" step="0.001" value="${v('km_progressive')??''}" placeholder="Ej. 0.125"></div><div><label class="field-label" for="icDate">Fecha y hora</label><input class="field" id="icDate" type="datetime-local" required value="${esc(v('occurred_at',new Date().toISOString().slice(0,16)).slice(0,16))}"></div><div><label class="field-label" for="icSeverity">Severidad</label><select class="field" id="icSeverity">${[['low','Baja'],['medium','Media'],['high','Alta'],['critical','Crítica']].map(([a,b])=>`<option value="${a}" ${v('severity','medium')===a?'selected':''}>${b}</option>`).join('')}</select></div><div><label class="field-label" for="icStatus">Estado</label><select class="field" id="icStatus">${[['open','Abierta'],['in_progress','En atención'],['resolved','Resuelta'],['closed','Cerrada']].map(([a,b])=>`<option value="${a}" ${v('status','open')===a?'selected':''}>${b}</option>`).join('')}</select></div><div class="full"><label class="field-label" for="icDescription">Descripción y hallazgos</label><textarea class="field" id="icDescription" rows="3">${esc(v('description',''))}</textarea></div><div class="full"><label class="field-label" for="icAction">Acción recomendada o ejecutada</label><textarea class="field" id="icAction" rows="2">${esc(v('action_taken',''))}</textarea></div><div class="full"><label class="field-label">Fotografía de evidencia</label><div style="display:flex;gap:8px;flex-wrap:wrap"><label class="btn" for="icPhotoCamera">📷 Tomar fotografía</label><input id="icPhotoCamera" class="inventory-file-input" type="file" accept="image/*" capture="environment"><label class="btn" for="icPhotoGallery">▧ Elegir de galería</label><input id="icPhotoGallery" class="inventory-file-input" type="file" accept="image/jpeg,image/png,image/webp"></div><div id="icPhotoPreview" class="inventory-photo-preview">${oldPhoto?'Hay una fotografía guardada. Si eliges otra, se reemplazará.':'No se ha seleccionado fotografía.'}</div></div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="incident-save" data-id="${esc(item?.id||'')}">Guardar incidencia</button>`);const roadSel=$('#icRoad'),segSel=$('#icSegment');const filter=()=>{[...segSel.options].forEach(o=>{if(o.value)o.hidden=o.dataset.roadId!==roadSel.value});if(segSel.selectedOptions[0]?.hidden)segSel.value=''};roadSel.addEventListener('change',filter);filter();if(oldPhoto?.path){window.geoSupabase.storage.from(oldPhoto.bucket||'geotracia-evidencias').createSignedUrl(oldPhoto.path,300).then(({data})=>{const p=$('#icPhotoPreview');if(p&&data?.signedUrl)p.innerHTML=`<img src="${esc(data.signedUrl)}" alt="Fotografía actual" style="max-width:100%;max-height:180px;border-radius:10px"><div class="sub">Fotografía actual; elegir otra la reemplaza.</div>`})}}
async function handleIncidentPhoto(input){const file=input.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Formato no admitido. Usa JPG, PNG o WEBP.');input.value='';return}if(file.size>10*1024*1024){toast('La fotografía supera el límite de 10 MB.');input.value='';return}incidentPhotoFile=file;const p=$('#icPhotoPreview');if(p){if(incidentPhotoPreviewUrl)URL.revokeObjectURL(incidentPhotoPreviewUrl);incidentPhotoPreviewUrl=URL.createObjectURL(file);p.innerHTML=`<img src="${incidentPhotoPreviewUrl}" alt="Vista previa" style="display:block;max-width:100%;max-height:220px;object-fit:contain;border-radius:10px"><div class="sub">${esc(file.name)} · ${(file.size/1024/1024).toFixed(2)} MB</div>`;p.scrollIntoView({behavior:'smooth',block:'nearest'})}}
async function saveIncident(id=''){const form=$('#incidentForm');if(!form?.reportValidity())return;if(!geoOrg||!incidentProjectId||!window.geoSupabase)return toast('La sesión o el proyecto no están disponibles.');const road=incidentRoads.find(r=>r.id===$('#icRoad').value);if(!road)return toast('Selecciona un camino válido.');const segmentId=$('#icSegment').value||null,segment=incidentSegments.find(s=>s.id===segmentId);if(segmentId&&(!segment||segment.road_id!==road.id))return toast('El tramo seleccionado no pertenece al camino.');const km=$('#icKm').value===''?null:Number($('#icKm').value);if(km!=null&&segment&&(km<Number(segment.start_km)||km>Number(segment.end_km)))return toast('La progresiva debe estar dentro del rango del tramo.');if(km!=null&&!inventoryLinePoint(incidentRoadGeometries[road.id]?.geojson,km,incidentRoadGeometries[road.id]?.length_m))return toast('No se pudo calcular la ubicación: verifica la geometría y la progresiva.');const old=incidentRows.find(x=>x.id===id),meta=old?.metadata&&typeof old.metadata==='object'?old.metadata:{};const payload={organization_id:geoOrg.id,project_id:incidentProjectId,road_id:road.id,segment_id:segmentId,code:$('#icCode').value.trim(),title:$('#icTitle').value.trim(),incident_type:$('#icType').value,severity:$('#icSeverity').value,status:$('#icStatus').value,km_progressive:km,occurred_at:$('#icDate').value?new Date($('#icDate').value).toISOString():new Date().toISOString(),description:$('#icDescription').value.trim(),action_taken:$('#icAction').value.trim(),metadata:meta,created_by:geoCurrentUser?.id||null,updated_at:new Date().toISOString()};const button=$('[data-action="incident-save"]');if(button){button.disabled=true;button.textContent='Guardando…'}try{let saved;if(id){const q=await window.geoSupabase.from('road_incidents').update(payload).eq('id',id).eq('organization_id',geoOrg.id).eq('project_id',incidentProjectId).select('id').single();if(q.error)throw q.error;saved=q.data}else{const q=await window.geoSupabase.from('road_incidents').insert(payload).select('id').single();if(q.error)throw q.error;saved=q.data}if(!saved?.id)throw new Error('Supabase no confirmó el guardado.');if(incidentPhotoFile){const file=incidentPhotoFile,ext=({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'})[file.type]||'jpg',path=`${geoOrg.id}/road-incidents/${saved.id}/${Date.now()}.${ext}`;const {error}=await window.geoSupabase.storage.from('geotracia-evidencias').upload(path,file,{contentType:file.type,upsert:true});if(error)throw new Error('La incidencia se guardó, pero falló la carga de la fotografía: '+error.message);const photo={bucket:'geotracia-evidencias',path,file_name:file.name,mime_type:file.type,size:file.size,uploaded_at:new Date().toISOString()};const {error:me}=await window.geoSupabase.from('road_incidents').update({metadata:{...meta,incident_photo:photo},updated_at:new Date().toISOString()}).eq('id',saved.id).eq('organization_id',geoOrg.id).eq('project_id',incidentProjectId);if(me)throw new Error('La incidencia y la fotografía se cargaron, pero falló guardar su referencia: '+me.message)}$('#dialog').close();incidentPhotoFile=null;if(incidentPhotoPreviewUrl)URL.revokeObjectURL(incidentPhotoPreviewUrl);incidentPhotoPreviewUrl='';toast(id?'Incidencia actualizada en Supabase':'Incidencia guardada en Supabase');await loadIncidentData(incidentProjectId)}catch(err){console.error('[GEOTRACIA] Error guardando incidencia:',err);toast('No se pudo completar el guardado: '+(err?.message||err?.details||'Error de Supabase'));if(button){button.disabled=false;button.textContent='Guardar incidencia'}}}
async function viewIncident(id){const x=incidentRows.find(r=>r.id===id);if(!x)return;const r=incidentRoads.find(q=>q.id===x.road_id),s=incidentSegments.find(q=>q.id===x.segment_id);let photo='<div class="full"><label class="field-label">Fotografía</label><p>No hay fotografía adjunta.</p></div>';const p=x.metadata?.incident_photo;if(p?.path){const {data,error}=await window.geoSupabase.storage.from(p.bucket||'geotracia-evidencias').createSignedUrl(p.path,300);if(!error&&data?.signedUrl)photo=`<div class="full"><label class="field-label">Fotografía de evidencia</label><img src="${esc(data.signedUrl)}" alt="Evidencia de incidencia" style="max-width:100%;max-height:320px;object-fit:contain;border-radius:12px"><div class="sub">${esc(p.file_name||'Fotografía adjunta')}</div></div>`}dialog(esc(x.title),`<div class="form-grid">${photo}<div><label class="field-label">Código</label>${esc(x.code)}</div><div><label class="field-label">Tipo</label>${esc(x.incident_type)}</div><div class="full"><label class="field-label">Camino</label>${esc(r?.code||'—')} · ${esc(r?.name||'')}</div><div><label class="field-label">Tramo</label>${esc(s?.code||'Camino completo')}</div><div><label class="field-label">Progresiva</label>${x.km_progressive==null?'—':Number(x.km_progressive).toFixed(3)+' km'}</div><div><label class="field-label">Severidad</label>${esc(x.severity||'—')}</div><div><label class="field-label">Estado</label>${esc(({open:'Abierta',in_progress:'En atención',resolved:'Resuelta',closed:'Cerrada'})[x.status]||x.status)}</div><div class="full"><label class="field-label">Descripción</label><p>${esc(x.description||'—')}</p></div><div class="full"><label class="field-label">Acción recomendada/ejecutada</label><p>${esc(x.action_taken||'—')}</p></div></div>`,`<button class="btn" data-close>Cerrar</button><button class="btn" data-action="incident-edit" data-id="${esc(x.id)}">Editar</button>`)}
function editIncidentStatus(id){const x=incidentRows.find(r=>r.id===id);if(!x)return;dialog('Actualizar estado de incidencia',`<div class="form-grid"><div class="full"><label class="field-label" for="icStatusOnly">Estado</label><select class="field" id="icStatusOnly">${[['open','Abierta'],['in_progress','En atención'],['resolved','Resuelta'],['closed','Cerrada']].map(([a,b])=>`<option value="${a}" ${x.status===a?'selected':''}>${b}</option>`).join('')}</select></div></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="incident-status-save" data-id="${esc(id)}">Guardar estado</button>`)}
async function saveIncidentStatus(id){const x=incidentRows.find(r=>r.id===id);if(!x||!window.geoSupabase)return;const status=$('#icStatusOnly')?.value;if(!status)return;const {error}=await window.geoSupabase.from('road_incidents').update({status,updated_at:new Date().toISOString()}).eq('id',id).eq('organization_id',geoOrg.id).eq('project_id',incidentProjectId);if(error)return toast('No se pudo actualizar el estado: '+error.message);$('#dialog').close();toast('Estado de incidencia actualizado');await loadIncidentData(incidentProjectId)}
// Operaciones y permisos: datos persistidos en Supabase, sin registros de muestra.
let opsProjectId='', opsRows=[], opsAssignments=[], opsMembers=[], opsLoading=false, opsError='', opsRoads=[], opsRoadGeometries={}, opsMapInstance=null, opsMapLayers=[];
const opsStatusLabel={planned:'Programada',in_progress:'En ejecución',paused:'Pausada',completed:'Completada',cancelled:'Cancelada'};
const opsTypeLabel={operation:'Operación',service:'Servicio'};
const opsRoleLabel={project_admin:'Administrador del proyecto',supervisor:'Supervisor',operator:'Operador',viewer:'Solo lectura'};
function operationsModule(){
 const projects=geoProjects.filter(p=>p.status!=='archived');
 const selected=projects.find(p=>p.id===opsProjectId);
 const rows=opsRows;
 const done=rows.filter(x=>x.status==='completed').length, open=rows.filter(x=>['planned','in_progress'].includes(x.status)).length;
 const opts=projects.map(p=>`<option value="${esc(p.id)}" ${p.id===opsProjectId?'selected':''}>${esc(p.code?p.code+' · ':'')}${esc(p.name)}</option>`).join('');
 const table=rows.map(x=>`<tr><td><b>${esc(x.code||'—')}</b><div class="sub">${esc(opsTypeLabel[x.kind]||x.kind)}</div></td><td><b>${esc(x.title)}</b><div class="sub">${esc(opsRoads.find(r=>r.id===x.road_id)?.name||x.location||'Sin ubicación')}<div class="sub">${x.km_progressive==null?'Progresiva no registrada':`Km ${Number(x.km_progressive).toFixed(3)}`}</div></div></td><td>${badge(opsStatusLabel[x.status]||x.status,x.status==='completed'?'success':x.status==='paused'?'warning':'info')}</td><td>${badge(({low:'Baja',normal:'Normal',high:'Alta',critical:'Crítica'})[x.priority]||'Normal',x.priority==='critical'?'danger':x.priority==='high'?'warning':'info')}</td><td>${esc(x.assignee_name||'Sin asignar')}</td><td>${esc(x.start_date||'—')}<div class="sub">Hasta ${esc(x.due_date||'—')}</div></td><td><button class="btn" data-action="ops-view" data-id="${esc(x.id)}">Ver</button> <button class="btn" data-action="ops-edit" data-id="${esc(x.id)}">Editar</button></td></tr>`).join('');
 return `${head('Operaciones y permisos','Control operativo, servicios, responsables y acceso por proyecto.',btn('↻ Actualizar','ops-reload')+btn('↓ Exportar CSV','ops-export')+btn('＋ Nueva operación','ops-new','primary'))}
 <section class="panel"><div class="panel-head"><div><h2>Proyecto de trabajo</h2><div class="sub">Los registros se consultan desde Supabase y quedan aislados por organización y proyecto.</div></div></div><div class="panel-body"><label class="field-label" for="opsProjectSelect">Proyecto</label><select class="field" id="opsProjectSelect" ${projects.length?'':'disabled'}><option value="">Seleccionar proyecto…</option>${opts}</select>${!window.geoSupabase?'<div class="note">Supabase no está configurado. No se mostrarán datos de ejemplo.</div>':''}${!geoOrg?'<div class="note">No se ha cargado la organización del usuario. Abre Proyectos o inicia sesión.</div>':''}${opsError?`<div class="note">${esc(opsError)}</div>`:''}${opsLoading?'<p class="sub">Cargando operaciones y permisos…</p>':''}</div></section>
 <div class="kpis">${kpi(rows.length,'Operaciones y servicios','Registros del proyecto','▤')}${kpi(open,'Abiertas','Programadas o en ejecución','◷','amber')}${kpi(done,'Completadas','Cierre registrado','✓','teal')}${kpi(opsAssignments.length,'Asignaciones','Responsables y equipos','♙','purple')}</div>
 <div class="module-layout"><div class="stack">${panel('Registro operativo',`<div class="table-scroll"><table><thead><tr><th>CÓDIGO / TIPO</th><th>OPERACIÓN / SERVICIO</th><th>ESTADO</th><th>PRIORIDAD</th><th>RESPONSABLE</th><th>FECHAS</th><th>ACCIONES</th></tr></thead><tbody>${table||`<tr><td colspan="7"><div class="empty">${opsLoading?'Consultando datos…':'No hay operaciones para este proyecto. Crea la primera operación o servicio.'}</div></td></tr>`}</tbody></table></div><div class="pagination"><span>${rows.length} registros persistidos</span>${btn('＋ Nueva operación','ops-new','primary')}</div>`,'Operaciones y servicios con persistencia real en PostgreSQL')}${panel('Asignaciones del proyecto',`<div class="table-scroll"><table><thead><tr><th>OPERACIÓN</th><th>PERSONA</th><th>FUNCIÓN</th><th>ASIGNACIÓN</th></tr></thead><tbody>${opsAssignments.map(a=>`<tr><td>${esc(a.operation_title||a.operation_id)}</td><td>${esc(a.member_name||a.user_email||'Usuario')}</td><td>${esc(a.assignment_role||'Responsable')}</td><td>${esc(a.status||'Activa')}</td></tr>`).join('')||'<tr><td colspan="4">No hay asignaciones registradas.</td></tr>'}</tbody></table></div><div class="panel-body">${btn('＋ Asignar responsable','ops-assign', 'primary')}</div>`,'Responsables vinculados a operaciones del proyecto')}</div>
 <div class="stack">${panel('Mapa de operaciones',`<div id="opsMap" style="height:320px;min-height:280px;border-radius:12px;overflow:hidden;background:#eef2f7"></div><p id="opsMapStatus" class="sub" style="margin-top:10px">Cargando caminos y ubicaciones…</p>`,'Caminos del proyecto y puntos de operación')}${panel('Accesos y roles del proyecto',`<div class="sub" style="margin-bottom:12px">Los permisos se aplican en Supabase mediante RLS; esta pantalla no sustituye las políticas del servidor.</div><div class="table-scroll"><table><thead><tr><th>MIEMBRO</th><th>ROL</th><th>ESTADO</th><th></th></tr></thead><tbody>${opsMembers.map(m=>`<tr><td><b>${esc(m.display_name||m.email||'Miembro')}</b><div class="sub">${esc(m.email||'')}</div></td><td>${esc(opsRoleLabel[m.project_role]||m.project_role||'Solo lectura')}</td><td>${badge(m.active?'Activo':'Inactivo',m.active?'success':'warning')}</td><td><button class="btn" data-action="ops-role-edit" data-id="${esc(m.id)}">Cambiar rol</button></td></tr>`).join('')||'<tr><td colspan="4">No se han cargado miembros del proyecto.</td></tr>'}</tbody></table></div><div class="panel-body">${btn('＋ Dar acceso al proyecto','ops-access','primary')}</div>`,'Miembros y permisos por proyecto')}${panel('Trazabilidad',`<div class="settings-row"><span class="setting-icon">▤</span><span class="setting-copy"><b>Auditoría de operaciones</b><small>Creaciones y cambios registran actor, entidad y fecha.</small></span></div><div class="settings-row"><span class="setting-icon">♢</span><span class="setting-copy"><b>Control de acceso</b><small>La base de datos valida la membresía y el rol.</small></span></div>`,'Seguridad y seguimiento')}</div></div>`;
}
async function loadOperationsData(projectId=opsProjectId){
 opsProjectId=projectId||'';opsRows=[];opsAssignments=[];opsMembers=[];opsError='';
 if(!window.geoSupabase){opsError='Supabase no está configurado.';show();return}
 if(!geoProjects.length){opsError='No hay proyectos cargados para esta organización.';show();return}
 if(!opsProjectId){opsProjectId=geoProjects.find(p=>p.status!=='archived')?.id||''}
 if(!opsProjectId){opsError='Selecciona o crea un proyecto para continuar.';show();return}
 opsLoading=true;show();
 try{
  const c=window.geoSupabase;
  const [r,a,m,roads]=await Promise.all([
   c.from('geotracia_operations').select('*').eq('organization_id',geoOrg.id).eq('project_id',opsProjectId).order('created_at',{ascending:false}),
   c.from('geotracia_operation_assignments').select('*, geotracia_operations(title)').eq('organization_id',geoOrg.id).eq('project_id',opsProjectId).order('created_at',{ascending:false}),
   c.from('geotracia_project_access').select('*').eq('organization_id',geoOrg.id).eq('project_id',opsProjectId).order('created_at',{ascending:false}),
   c.from('roads').select('id,organization_id,project_id,code,name,length_m').eq('organization_id',geoOrg.id).eq('project_id',opsProjectId).order('code')
  ]);
  if(r.error)throw r.error;if(a.error)throw a.error;if(m.error)throw m.error;if(roads.error)throw roads.error;
  opsRows=r.data||[];opsAssignments=(a.data||[]).map(x=>({...x,operation_title:x.geotracia_operations?.title}));opsMembers=m.data||[];opsRoads=roads.data||[];opsRoadGeometries={};
  try{const gr=await c.rpc('geotracia_inventory_road_geometries',{p_project_id:opsProjectId});if(!gr.error)for(const g of (gr.data||[])){let geom=g.road_geojson||g.geojson||g.geom_geojson;if(typeof geom==='string'){try{geom=JSON.parse(geom)}catch{geom=null}}if(g.road_id&&geom)opsRoadGeometries[g.road_id]={geojson:geom,length_m:g.length_m==null?null:Number(g.length_m)}}}catch(geoErr){console.warn('[GEOTRACIA] No se cargaron geometrías de operaciones',geoErr)}
 }catch(e){opsError='No se pudieron cargar los datos: '+(e.message||'error de Supabase')+'. Ejecuta la migración SQL del módulo y vuelve a intentar.'}
 finally{opsLoading=false;show()}
}
function renderOperationsMap(){
 const el=$('#opsMap');if(!el||!window.L)return;
 if(opsMapInstance){try{opsMapInstance.remove()}catch{}opsMapInstance=null;opsMapLayers=[]}
 const map=L.map(el,{doubleClickZoom:false}).setView([-38.7359,-72.5904],7);opsMapInstance=map;
 L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);
 const bounds=[];let roadsShown=0,pointsShown=0;
 const lines=g=>{if(!g)return[];if(g.type==='Feature')g=g.geometry;if(!g)return[];if(g.type==='LineString')return[g.coordinates||[]];if(g.type==='MultiLineString')return g.coordinates||[];if(g.type==='GeometryCollection')return(g.geometries||[]).flatMap(x=>x.type==='LineString'?[x.coordinates||[]]:x.type==='MultiLineString'?(x.coordinates||[]):[]);return[]};
 const normalizedGeo=g=>{if(!g)return null;if(g.type==='Feature')return g.geometry;return g};
 opsRoads.forEach(r=>{const g=opsRoadGeometries[r.id];if(!g)return;lines(normalizedGeo(g.geojson)).forEach(coords=>{const ll=coords.filter(c=>Array.isArray(c)&&c.length>=2).map(c=>[Number(c[1]),Number(c[0])]).filter(c=>Number.isFinite(c[0])&&Number.isFinite(c[1]));if(ll.length<2)return;const p=L.polyline(ll,{color:'#94a3b8',weight:4,opacity:.8}).addTo(map);p.bindTooltip(`${esc(r.code||'Camino')} · ${esc(r.name||'')}`);opsMapLayers.push(p);ll.forEach(c=>bounds.push(c));roadsShown++})});
 opsRows.forEach(x=>{const g=opsRoadGeometries[x.road_id];if(!g)return;const point=x.km_progressive!=null?inventoryLinePoint(normalizedGeo(g.geojson),Number(x.km_progressive),g.length_m):null;let ll;
  if(point)ll=[point.lat,point.lng];else if(x.km_progressive==null){const coords=lines(normalizedGeo(g.geojson)).find(a=>Array.isArray(a)&&a.length>=2);const c=coords?.[Math.floor((coords.length-1)/2)];if(c)ll=[Number(c[1]),Number(c[0])]}
  if(!ll||!Number.isFinite(ll[0])||!Number.isFinite(ll[1]))return;
  const color=x.status==='completed'?'#16a34a':x.status==='paused'?'#dc2626':x.status==='in_progress'?'#ea580c':'#2563eb';const m=L.circleMarker(ll,{radius:9,color:'#fff',weight:2,fillColor:color,fillOpacity:.98}).addTo(map);const road=opsRoads.find(r=>r.id===x.road_id);const prog=x.km_progressive==null?'Progresiva no registrada':`Km ${Number(x.km_progressive).toFixed(3).replace('.',',')}`;
  m.bindTooltip(`${esc(x.code||'Operación')} · ${esc(x.title)}`);m.bindPopup(`<b>${esc(x.code||'')}</b><br>${esc(x.title)}<br>${esc(road?.code||'Camino')} · ${esc(road?.name||'')}<br>${esc(prog)}<br>Estado: ${esc(opsStatusLabel[x.status]||x.status)}<br>Responsable: ${esc(x.assignee_name||'Sin asignar')}`);opsMapLayers.push(m);bounds.push(ll);pointsShown++;
 });
 if(bounds.length)map.fitBounds(L.latLngBounds(bounds),{padding:[24,24],maxZoom:15});const status=$('#opsMapStatus');
 if(status)status.textContent=!opsRoads.length?'Este proyecto no tiene caminos registrados.':!roadsShown?'Hay caminos, pero no se recibió geometría del RPC geotracia_inventory_road_geometries. Revisa geometrías y permisos de Supabase.':`${roadsShown} geometrías de camino · ${pointsShown} operaciones ubicadas. Las operaciones con progresiva se marcan en el punto calculado sobre la geometría vial.`;
 setTimeout(()=>map.invalidateSize(),160)
}
