async function saveProjectAccess(id=''){const form=$('#opsAccessForm'),button=$('#dialogFoot [data-action="ops-access-save"]'),status=$('#opsAccessStatus');const report=msg=>{if(status){status.textContent=msg;status.style.color='#b42318';status.style.background='#fff1f0';status.style.border='1px solid #f3b7b3';status.style.borderRadius='8px';status.style.padding='10px 12px'}else console.error('[GEOTRACIA] '+msg)};if(!geoOrg||!opsProjectId)return report('Selecciona una organización y un proyecto.');if(!form)return report('No se encontró el formulario.');const email=String($('#opsAccessEmail')?.value||'').trim().toLowerCase();const displayName=String($('#opsAccessName')?.value||'').trim();const role=$('#opsAccessRole')?.value||'viewer';const active=$('#opsAccessActive')?.checked===true;if(!id&&(!email||!/^\S+@\S+\.\S+$/.test(email)))return report('Ingresa un correo electrónico válido.');try{if(button){button.disabled=true;button.textContent='Guardando…'}if(status){status.style.color='';status.style.background='#eff6ff';status.style.border='1px solid #bfdbfe';status.textContent=id?'Actualizando permisos…':'Validando cuenta, membresía y permisos…'}let result;if(id){const payload={display_name:displayName||null,project_role:role,active,updated_at:new Date().toISOString()};result=await window.geoSupabase.from('geotracia_project_access').update(payload).eq('id',id).eq('organization_id',geoOrg.id).eq('project_id',opsProjectId).select('id').maybeSingle();if(result.error)throw result.error;if(!result.data)throw new Error('No se actualizó ningún acceso. Comprueba que tengas rol project_admin en este proyecto.')}else{result=await window.geoSupabase.rpc('geotracia_grant_project_access_by_email',{p_organization_id:geoOrg.id,p_project_id:opsProjectId,p_email:email,p_display_name:displayName||null,p_project_role:role,p_active:active});if(result.error)throw result.error;}try{await window.geoSupabase.from('audit_logs').insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id||null,action:id?'project_access.updated':'project_access.created',entity_table:'geotracia_project_access',entity_id:id||result.data||null,details:{project_id:opsProjectId,email:email||null,role,active}})}catch(e){console.warn('[GEOTRACIA] No se pudo registrar auditoría',e)}$('#dialog').close();toast('Permisos guardados correctamente.');await loadOperationsData(opsProjectId)}catch(e){console.error('[GEOTRACIA] Error al guardar acceso',e);report('No se pudieron guardar los permisos: '+(e?.message||'error desconocido de Supabase'))}finally{if(button){button.disabled=false;button.textContent='Guardar permisos'}}}
function exportOperations(){const cols=['code','kind','title','location','status','priority','assignee_name','start_date','due_date','description','notes'];const labels=['Código','Tipo','Título','Ubicación','Estado','Prioridad','Responsable','Inicio','Fecha límite','Descripción','Notas'];const csv=[labels,...opsRows.map(x=>cols.map(k=>x[k]??''))].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');exportFile('geotracia-operaciones.csv','\ufeff'+csv,'text/csv;charset=utf-8');toast('Operaciones exportadas a CSV')}

